-- N5 · n5-day-at-the-park · A day at the park
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n5-day-at-the-park', 'lang-ja', ll.id, 'n5-day-at-the-park', 'こうえんの一日', 'A day at the park', false, 15
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n5-day-at-the-park-l0', 'rdg-ja-n5-day-at-the-park', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n5-day-at-the-park-l1', 'rdg-ja-n5-day-at-the-park', 1, 0, '日曜日、友だちとこうえんへ行きました。', 'にちようび、ともだち と こうえん え いきました。', '[{"t":"日曜日","r":"にちようび"},{"t":"、"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"と"},{"t":"こうえん"},{"t":"へ"},{"t":"行","r":"い"},{"t":"きました"},{"t":"。"}]'::jsonb, 'On Sunday, I went to the park with a friend.'),
  ('rdg-ja-n5-day-at-the-park-l2', 'rdg-ja-n5-day-at-the-park', 2, 1, '天気は、とてもよかったです。', 'てんき わ、とても よかった です。', '[{"t":"天気","r":"てんき"},{"t":"は"},{"t":"、"},{"t":"とても"},{"t":"よかった"},{"t":"です"},{"t":"。"}]'::jsonb, 'The weather was very good.'),
  ('rdg-ja-n5-day-at-the-park-l3', 'rdg-ja-n5-day-at-the-park', 3, 1, 'そらは青くて、風はあたたかかったです。', 'そら わ あおくて、かぜ わ あたたかかった です。', '[{"t":"そら"},{"t":"は"},{"t":"青","r":"あお"},{"t":"くて"},{"t":"、"},{"t":"風","r":"かぜ"},{"t":"は"},{"t":"あたたかかった"},{"t":"です"},{"t":"。"}]'::jsonb, 'The sky was blue and the wind was warm.'),
  ('rdg-ja-n5-day-at-the-park-l4', 'rdg-ja-n5-day-at-the-park', 4, 1, '大きい木の下に、すわりました。', 'おおきい き の した に、すわりました。', '[{"t":"大","r":"おお"},{"t":"きい"},{"t":"木","r":"き"},{"t":"の"},{"t":"下","r":"した"},{"t":"に"},{"t":"、"},{"t":"すわりました"},{"t":"。"}]'::jsonb, 'I sat under a big tree.'),
  ('rdg-ja-n5-day-at-the-park-l5', 'rdg-ja-n5-day-at-the-park', 5, 2, '子どもたちが、あそんでいました。', 'こどもたち が、あそんで いました。', '[{"t":"子","r":"こ"},{"t":"ども"},{"t":"たち"},{"t":"が"},{"t":"、"},{"t":"あそんで"},{"t":"いました"},{"t":"。"}]'::jsonb, 'Children were playing.'),
  ('rdg-ja-n5-day-at-the-park-l6', 'rdg-ja-n5-day-at-the-park', 6, 2, '小さい犬も、走っていました。', 'ちいさい いぬ も、はしって いました。', '[{"t":"小","r":"ちい"},{"t":"さい"},{"t":"犬","r":"いぬ"},{"t":"も"},{"t":"、"},{"t":"走","r":"はし"},{"t":"って"},{"t":"いました"},{"t":"。"}]'::jsonb, 'A small dog was running too.'),
  ('rdg-ja-n5-day-at-the-park-l7', 'rdg-ja-n5-day-at-the-park', 7, 2, 'わたしは、しずかに見ていました。', 'わたし わ、しずか に みて いました。', '[{"t":"わたし"},{"t":"は"},{"t":"、"},{"t":"しずか"},{"t":"に"},{"t":"見","r":"み"},{"t":"て"},{"t":"いました"},{"t":"。"}]'::jsonb, 'I watched them quietly.'),
  ('rdg-ja-n5-day-at-the-park-l8', 'rdg-ja-n5-day-at-the-park', 8, 3, 'いっしょに、おべんとうを食べました。', 'いっしょ に、おべんとう お たべました。', '[{"t":"いっしょ"},{"t":"に"},{"t":"、"},{"t":"おべんとう"},{"t":"を"},{"t":"食","r":"た"},{"t":"べました"},{"t":"。"}]'::jsonb, 'We ate packed lunches together.'),
  ('rdg-ja-n5-day-at-the-park-l9', 'rdg-ja-n5-day-at-the-park', 9, 3, 'おにぎりは、とてもおいしかったです。', 'おにぎり わ、とても おいしかった です。', '[{"t":"おにぎり"},{"t":"は"},{"t":"、"},{"t":"とても"},{"t":"おいしかった"},{"t":"です"},{"t":"。"}]'::jsonb, 'The rice balls were very tasty.'),
  ('rdg-ja-n5-day-at-the-park-l10', 'rdg-ja-n5-day-at-the-park', 10, 3, 'そして、お茶を飲みました。', 'そして、おちゃ お のみました。', '[{"t":"そして"},{"t":"、"},{"t":"お"},{"t":"茶","r":"ちゃ"},{"t":"を"},{"t":"飲","r":"の"},{"t":"みました"},{"t":"。"}]'::jsonb, 'And we drank tea.'),
  ('rdg-ja-n5-day-at-the-park-l11', 'rdg-ja-n5-day-at-the-park', 11, 4, '午後は、本を読みました。', 'ごご わ、ほん お よみました。', '[{"t":"午後","r":"ごご"},{"t":"は"},{"t":"、"},{"t":"本","r":"ほん"},{"t":"を"},{"t":"読","r":"よ"},{"t":"みました"},{"t":"。"}]'::jsonb, 'In the afternoon, I read a book.'),
  ('rdg-ja-n5-day-at-the-park-l12', 'rdg-ja-n5-day-at-the-park', 12, 4, 'ときどき、花を見ました。', 'ときどき、はな お みました。', '[{"t":"ときどき"},{"t":"、"},{"t":"花","r":"はな"},{"t":"を"},{"t":"見","r":"み"},{"t":"ました"},{"t":"。"}]'::jsonb, 'Now and then, I looked at the flowers.'),
  ('rdg-ja-n5-day-at-the-park-l13', 'rdg-ja-n5-day-at-the-park', 13, 5, '五時に、家へ帰りました。', 'ごじ に、いえ え かえりました。', '[{"t":"五時","r":"ごじ"},{"t":"に"},{"t":"、"},{"t":"家","r":"いえ"},{"t":"へ"},{"t":"帰","r":"かえ"},{"t":"りました"},{"t":"。"}]'::jsonb, 'I went home at five.'),
  ('rdg-ja-n5-day-at-the-park-l14', 'rdg-ja-n5-day-at-the-park', 14, 5, 'また、行きたいです。', 'また、いきたい です。', '[{"t":"また"},{"t":"、"},{"t":"行","r":"い"},{"t":"きたい"},{"t":"です"},{"t":"。"}]'::jsonb, 'I want to go again.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n5-day-at-the-park')
ON CONFLICT (reading_id, index) DO NOTHING;

