SELECT v.* FROM (VALUES
  ('rdg-ja-n5-my-favourite-season-l0', 'rdg-ja-n5-my-favourite-season', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n5-my-favourite-season-l1', 'rdg-ja-n5-my-favourite-season', 1, 0, '今日は、すきなきせつの話をします。', 'きょう わ、すきな きせつ の はなし お します。', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"すきな"},{"t":"きせつ"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'Today I will talk about my favourite season.'),
  ('rdg-ja-n5-my-favourite-season-l2', 'rdg-ja-n5-my-favourite-season', 2, 1, 'わたしは、あきがいちばん好きです。', 'わたし わ、あき が いちばん すき です。', '[{"t":"わたし"},{"t":"は"},{"t":"、"},{"t":"あき"},{"t":"が"},{"t":"いちばん"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":"。"}]'::jsonb, 'I like autumn the best.'),
  ('rdg-ja-n5-my-favourite-season-l3', 'rdg-ja-n5-my-favourite-season', 3, 1, 'あきは、すずしいです。', 'あき わ、すずしい です。', '[{"t":"あき"},{"t":"は"},{"t":"、"},{"t":"すずしい"},{"t":"です"},{"t":"。"}]'::jsonb, 'Autumn is cool.'),
  ('rdg-ja-n5-my-favourite-season-l4', 'rdg-ja-n5-my-favourite-season', 4, 1, '天気のいい日も多いです。', 'てんき の いい ひ も おおい です。', '[{"t":"天気","r":"てんき"},{"t":"の"},{"t":"いい"},{"t":"日","r":"ひ"},{"t":"も"},{"t":"多","r":"おお"},{"t":"い"},{"t":"です"},{"t":"。"}]'::jsonb, 'There are many fine days, too.'),
  ('rdg-ja-n5-my-favourite-season-l5', 'rdg-ja-n5-my-favourite-season', 5, 2, 'あきは、本を読むのが好きです。', 'あき わ、ほん お よむ の が すき です。', '[{"t":"あき"},{"t":"は"},{"t":"、"},{"t":"本","r":"ほん"},{"t":"を"},{"t":"読","r":"よ"},{"t":"む"},{"t":"の"},{"t":"が"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":"。"}]'::jsonb, 'In autumn, I like reading books.'),
  ('rdg-ja-n5-my-favourite-season-l6', 'rdg-ja-n5-my-favourite-season', 6, 2, '夜が長いですから。', 'よる が ながい です から。', '[{"t":"夜","r":"よる"},{"t":"が"},{"t":"長","r":"なが"},{"t":"い"},{"t":"ですから"},{"t":"。"}]'::jsonb, 'Because the nights are long.'),
  ('rdg-ja-n5-my-favourite-season-l7', 'rdg-ja-n5-my-favourite-season', 7, 2, 'あたたかいお茶も、おいしいです。', 'あたたかい おちゃ も、おいしい です。', '[{"t":"あたたかい"},{"t":"お"},{"t":"茶","r":"ちゃ"},{"t":"も"},{"t":"、"},{"t":"おいしい"},{"t":"です"},{"t":"。"}]'::jsonb, 'Warm tea tastes good too.'),
  ('rdg-ja-n5-my-favourite-season-l8', 'rdg-ja-n5-my-favourite-season', 8, 3, 'あきは、食べ物もおいしいです。', 'あき わ、たべもの も おいしい です。', '[{"t":"あき"},{"t":"は"},{"t":"、"},{"t":"食","r":"た"},{"t":"べ"},{"t":"物","r":"もの"},{"t":"も"},{"t":"おいしい"},{"t":"です"},{"t":"。"}]'::jsonb, 'In autumn, the food is delicious too.'),
  ('rdg-ja-n5-my-favourite-season-l9', 'rdg-ja-n5-my-favourite-season', 9, 3, 'くりやさかなが好きです。', 'くり や さかな が すき です。', '[{"t":"くり"},{"t":"や"},{"t":"さかな"},{"t":"が"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":"。"}]'::jsonb, 'I like chestnuts and fish.'),
  ('rdg-ja-n5-my-favourite-season-l10', 'rdg-ja-n5-my-favourite-season', 10, 3, 'あきは、よく食べます。', 'あき わ、よく たべます。', '[{"t":"あき"},{"t":"は"},{"t":"、"},{"t":"よく"},{"t":"食","r":"た"},{"t":"べます"},{"t":"。"}]'::jsonb, 'In autumn, I eat a lot.'),
  ('rdg-ja-n5-my-favourite-season-l11', 'rdg-ja-n5-my-favourite-season', 11, 4, '黄色い葉は、きれいです。', 'きいろい は わ、きれい です。', '[{"t":"黄色","r":"き"},{"t":"い"},{"t":"葉","r":"ろいは"},{"t":"は"},{"t":"、"},{"t":"きれい"},{"t":"です"},{"t":"。"}]'::jsonb, 'The yellow leaves are pretty.'),
  ('rdg-ja-n5-my-favourite-season-l12', 'rdg-ja-n5-my-favourite-season', 12, 4, 'わたしは、よく山へ行きます。', 'わたし わ、よく やま え いきます。', '[{"t":"わたし"},{"t":"は"},{"t":"、"},{"t":"よく"},{"t":"山","r":"やま"},{"t":"へ"},{"t":"行","r":"い"},{"t":"きます"},{"t":"。"}]'::jsonb, 'I often go to the mountains.'),
  ('rdg-ja-n5-my-favourite-season-l13', 'rdg-ja-n5-my-favourite-season', 13, 5, 'みなさんの好きなきせつは、何ですか。', 'みなさん の すきな きせつ わ、なん です か。', '[{"t":"みなさん"},{"t":"の"},{"t":"好","r":"す"},{"t":"き"},{"t":"な"},{"t":"きせつ"},{"t":"は"},{"t":"、"},{"t":"何","r":"なん"},{"t":"ですか"},{"t":"。"}]'::jsonb, 'What is your favourite season?')
