-- N5 · n5-breakfast · Breakfast
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n5-breakfast', 'lang-ja', ll.id, 'n5-breakfast', '朝ごはん', 'Breakfast', false, 17
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n5-breakfast-l0', 'rdg-ja-n5-breakfast', 0, 0, 'おはようございます。', 'おはよう ございます。', '[{"t":"おはようございます"},{"t":"。"}]'::jsonb, 'Good morning.'),
  ('rdg-ja-n5-breakfast-l1', 'rdg-ja-n5-breakfast', 1, 0, '今日は、朝ごはんの話をします。', 'きょう わ、あさごはん の はなし お します。', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"朝","r":"あさ"},{"t":"ごはん"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'Today I will talk about breakfast.'),
  ('rdg-ja-n5-breakfast-l2', 'rdg-ja-n5-breakfast', 2, 1, 'わたしは、毎朝、六時に起きます。', 'わたし わ、まいあさ、ろくじ に おきます。', '[{"t":"わたし"},{"t":"は"},{"t":"、"},{"t":"毎朝","r":"まいあさ"},{"t":"、"},{"t":"六時","r":"ろくじ"},{"t":"に"},{"t":"起","r":"お"},{"t":"きます"},{"t":"。"}]'::jsonb, 'Every morning, I get up at six.'),
  ('rdg-ja-n5-breakfast-l3', 'rdg-ja-n5-breakfast', 3, 1, 'そして、すぐに朝ごはんを作ります。', 'そして、すぐ に あさごはん お つくります。', '[{"t":"そして"},{"t":"、"},{"t":"すぐ"},{"t":"に"},{"t":"朝","r":"あさ"},{"t":"ごはん"},{"t":"を"},{"t":"作","r":"つく"},{"t":"ります"},{"t":"。"}]'::jsonb, 'Then I make breakfast right away.'),
  ('rdg-ja-n5-breakfast-l4', 'rdg-ja-n5-breakfast', 4, 2, 'たいてい、パンとたまごを食べます。', 'たいてい、パン と たまご お たべます。', '[{"t":"たいてい"},{"t":"、"},{"t":"パン"},{"t":"と"},{"t":"たまご"},{"t":"を"},{"t":"食","r":"た"},{"t":"べます"},{"t":"。"}]'::jsonb, 'Usually, I eat bread and eggs.'),
  ('rdg-ja-n5-breakfast-l5', 'rdg-ja-n5-breakfast', 5, 2, 'たまごは、小さいフライパンで作ります。', 'たまご わ、ちいさい フライパン で つくります。', '[{"t":"たまご"},{"t":"は"},{"t":"、"},{"t":"小","r":"ちい"},{"t":"さい"},{"t":"フライパン"},{"t":"で"},{"t":"作","r":"つく"},{"t":"ります"},{"t":"。"}]'::jsonb, 'I cook the eggs in a small frying pan.'),
  ('rdg-ja-n5-breakfast-l6', 'rdg-ja-n5-breakfast', 6, 2, 'ぎゅうにゅうも飲みます。', 'ぎゅうにゅう も のみます。', '[{"t":"ぎゅうにゅう"},{"t":"も"},{"t":"飲","r":"の"},{"t":"みます"},{"t":"。"}]'::jsonb, 'I drink milk too.'),
  ('rdg-ja-n5-breakfast-l7', 'rdg-ja-n5-breakfast', 7, 3, '日曜日は、ごはんを食べます。', 'にちようび わ、ごはん お たべます。', '[{"t":"日曜日","r":"にちようび"},{"t":"は"},{"t":"、"},{"t":"ごはん"},{"t":"を"},{"t":"食","r":"た"},{"t":"べます"},{"t":"。"}]'::jsonb, 'On Sundays, I eat rice.'),
  ('rdg-ja-n5-breakfast-l8', 'rdg-ja-n5-breakfast', 8, 3, 'みそしると、さかなも食べます。', 'みそしる と、さかな も たべます。', '[{"t":"みそしる"},{"t":"と"},{"t":"、"},{"t":"さかな"},{"t":"も"},{"t":"食","r":"た"},{"t":"べます"},{"t":"。"}]'::jsonb, 'I eat miso soup and fish too.'),
  ('rdg-ja-n5-breakfast-l9', 'rdg-ja-n5-breakfast', 9, 3, '母は、毎朝、ごはんを食べます。', 'はは わ、まいあさ、ごはん お たべます。', '[{"t":"母","r":"はは"},{"t":"は"},{"t":"、"},{"t":"毎朝","r":"まいあさ"},{"t":"、"},{"t":"ごはん"},{"t":"を"},{"t":"食","r":"た"},{"t":"べます"},{"t":"。"}]'::jsonb, 'My mother eats rice every morning.'),
  ('rdg-ja-n5-breakfast-l10', 'rdg-ja-n5-breakfast', 10, 4, '朝ごはんを食べると、元気になります。', 'あさごはん お たべる と、げんき に なります。', '[{"t":"朝","r":"あさ"},{"t":"ごはん"},{"t":"を"},{"t":"食","r":"た"},{"t":"べる"},{"t":"と"},{"t":"、"},{"t":"元気","r":"げんき"},{"t":"に"},{"t":"なります"},{"t":"。"}]'::jsonb, 'When I eat breakfast, I feel full of energy.'),
  ('rdg-ja-n5-breakfast-l11', 'rdg-ja-n5-breakfast', 11, 4, '食べないと、学校でねむくなります。', 'たべない と、がっこう で ねむく なります。', '[{"t":"食","r":"た"},{"t":"べない"},{"t":"と"},{"t":"、"},{"t":"学校","r":"がっこう"},{"t":"で"},{"t":"ねむく"},{"t":"なります"},{"t":"。"}]'::jsonb, 'If I don''t eat, I get sleepy at school.'),
  ('rdg-ja-n5-breakfast-l12', 'rdg-ja-n5-breakfast', 12, 5, 'みなさんは、朝ごはんに何を食べますか。', 'みなさん わ、あさごはん に なに お たべます か。', '[{"t":"みなさん"},{"t":"は"},{"t":"、"},{"t":"朝","r":"あさ"},{"t":"ごはん"},{"t":"に"},{"t":"何","r":"なに"},{"t":"を"},{"t":"食","r":"た"},{"t":"べます"},{"t":"か"},{"t":"。"}]'::jsonb, 'What do you eat for breakfast?')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n5-breakfast')
