INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n5-station-near-my-house-l0', 'rdg-ja-n5-station-near-my-house', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n5-station-near-my-house-l1', 'rdg-ja-n5-station-near-my-house', 1, 0, 'わたしの家の近くの駅の話をします。', 'わたし の いえ の ちかく の えき の はなし お します。', '[{"t":"わたし"},{"t":"の"},{"t":"家","r":"いえ"},{"t":"の"},{"t":"近","r":"ちか"},{"t":"く"},{"t":"の"},{"t":"駅","r":"えき"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'I will talk about the station near my house.'),
  ('rdg-ja-n5-station-near-my-house-l2', 'rdg-ja-n5-station-near-my-house', 2, 1, '駅は、家から歩いて五分です。', 'えき わ、いえ から あるいて ごふん です。', '[{"t":"駅","r":"えき"},{"t":"は"},{"t":"、"},{"t":"家","r":"いえ"},{"t":"から"},{"t":"歩","r":"ある"},{"t":"いて"},{"t":"五分","r":"ごふん"},{"t":"です"},{"t":"。"}]'::jsonb, 'The station is five minutes on foot from my house.'),
  ('rdg-ja-n5-station-near-my-house-l3', 'rdg-ja-n5-station-near-my-house', 3, 1, 'あまり大きくありません。', 'あまり おおきく ありません。', '[{"t":"あまり"},{"t":"大","r":"おお"},{"t":"き"},{"t":"く"},{"t":"ありません"},{"t":"。"}]'::jsonb, 'It is not very big.'),
  ('rdg-ja-n5-station-near-my-house-l4', 'rdg-ja-n5-station-near-my-house', 4, 1, 'でも、とてもべんりです。', 'でも、とても べんり です。', '[{"t":"でも"},{"t":"、"},{"t":"とても"},{"t":"べんり"},{"t":"です"},{"t":"。"}]'::jsonb, 'But it is very convenient.'),
  ('rdg-ja-n5-station-near-my-house-l5', 'rdg-ja-n5-station-near-my-house', 5, 2, '駅の前に、小さい店があります。', 'えき の まえ に、ちいさい みせ が あります。', '[{"t":"駅","r":"えき"},{"t":"の"},{"t":"前","r":"まえ"},{"t":"に"},{"t":"、"},{"t":"小","r":"ちい"},{"t":"さい"},{"t":"店","r":"みせ"},{"t":"が"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There is a small shop in front of the station.'),
  ('rdg-ja-n5-station-near-my-house-l6', 'rdg-ja-n5-station-near-my-house', 6, 2, '朝は、そこでお茶を買います。', 'あさ わ、そこ で おちゃ お かいます。', '[{"t":"朝","r":"あさ"},{"t":"は"},{"t":"、"},{"t":"そこ"},{"t":"で"},{"t":"お"},{"t":"茶","r":"ちゃ"},{"t":"を"},{"t":"買","r":"か"},{"t":"います"},{"t":"。"}]'::jsonb, 'In the morning, I buy tea there.'),
  ('rdg-ja-n5-station-near-my-house-l7', 'rdg-ja-n5-station-near-my-house', 7, 2, 'パンもおいしいです。', 'パン も おいしい です。', '[{"t":"パン"},{"t":"も"},{"t":"おいしい"},{"t":"です"},{"t":"。"}]'::jsonb, 'The bread is tasty too.'),
  ('rdg-ja-n5-station-near-my-house-l8', 'rdg-ja-n5-station-near-my-house', 8, 3, '毎朝、七時の電車に乗ります。', 'まいあさ、しちじ の でんしゃ に のります。', '[{"t":"毎朝","r":"まいあさ"},{"t":"、"},{"t":"七時","r":"しちじ"},{"t":"の"},{"t":"電車","r":"でんしゃ"},{"t":"に"},{"t":"乗","r":"の"},{"t":"ります"},{"t":"。"}]'::jsonb, 'Every morning, I take the seven o''clock train.'),
  ('rdg-ja-n5-station-near-my-house-l9', 'rdg-ja-n5-station-near-my-house', 9, 3, '人がたくさんいます。', 'ひと が たくさん います。', '[{"t":"人","r":"ひと"},{"t":"が"},{"t":"たくさん"},{"t":"います"},{"t":"。"}]'::jsonb, 'There are many people.'),
  ('rdg-ja-n5-station-near-my-house-l10', 'rdg-ja-n5-station-near-my-house', 10, 3, 'だから、いつも立っています。', 'だから、いつも たって います。', '[{"t":"だから"},{"t":"、"},{"t":"いつも"},{"t":"立","r":"た"},{"t":"って"},{"t":"います"},{"t":"。"}]'::jsonb, 'So I always stand.'),
  ('rdg-ja-n5-station-near-my-house-l11', 'rdg-ja-n5-station-near-my-house', 11, 4, '夜は、駅が静かです。', 'よる わ、えき が しずか です。', '[{"t":"夜","r":"よる"},{"t":"は"},{"t":"、"},{"t":"駅","r":"えき"},{"t":"が"},{"t":"静","r":"しず"},{"t":"か"},{"t":"です"},{"t":"。"}]'::jsonb, 'At night, the station is quiet.'),
  ('rdg-ja-n5-station-near-my-house-l12', 'rdg-ja-n5-station-near-my-house', 12, 4, '駅から家まで、ゆっくり歩きます。', 'えき から いえ まで、ゆっくり あるきます。', '[{"t":"駅","r":"えき"},{"t":"から"},{"t":"家","r":"いえ"},{"t":"まで"},{"t":"、"},{"t":"ゆっくり"},{"t":"歩","r":"ある"},{"t":"きます"},{"t":"。"}]'::jsonb, 'I walk slowly from the station to my house.'),
  ('rdg-ja-n5-station-near-my-house-l13', 'rdg-ja-n5-station-near-my-house', 13, 4, 'わたしは、この駅が好きです。', 'わたし わ、この えき が すき です。', '[{"t":"わたし"},{"t":"は"},{"t":"、"},{"t":"この"},{"t":"駅","r":"えき"},{"t":"が"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":"。"}]'::jsonb, 'I like this station.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n5-station-near-my-house')
ON CONFLICT (reading_id, index) DO NOTHING;

