INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n5-my-summer-holiday-l0', 'rdg-ja-n5-my-summer-holiday', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n5-my-summer-holiday-l1', 'rdg-ja-n5-my-summer-holiday', 1, 0, 'なつやすみの話をします。', 'なつやすみ の はなし お します。', '[{"t":"なつやすみ"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'I will talk about my summer holiday.'),
  ('rdg-ja-n5-my-summer-holiday-l2', 'rdg-ja-n5-my-summer-holiday', 2, 1, '今年のなつは、とてもあつかったです。', 'ことし の なつ わ、とても あつかった です。', '[{"t":"今年","r":"ことし"},{"t":"の"},{"t":"なつ"},{"t":"は"},{"t":"、"},{"t":"とても"},{"t":"あつかった"},{"t":"です"},{"t":"。"}]'::jsonb, 'This summer was very hot.'),
  ('rdg-ja-n5-my-summer-holiday-l3', 'rdg-ja-n5-my-summer-holiday', 3, 1, 'でも、わたしは元気でした。', 'でも、わたし わ げんき でした。', '[{"t":"でも"},{"t":"、"},{"t":"わたし"},{"t":"は"},{"t":"元気","r":"げんき"},{"t":"でした"},{"t":"。"}]'::jsonb, 'But I was well.'),
  ('rdg-ja-n5-my-summer-holiday-l4', 'rdg-ja-n5-my-summer-holiday', 4, 2, '八月に、家族と海へ行きました。', 'はちがつ に、かぞく と うみ え いきました。', '[{"t":"八月","r":"はちがつ"},{"t":"に"},{"t":"、"},{"t":"家族","r":"かぞく"},{"t":"と"},{"t":"海","r":"うみ"},{"t":"へ"},{"t":"行","r":"い"},{"t":"きました"},{"t":"。"}]'::jsonb, 'In August, I went to the sea with my family.'),
  ('rdg-ja-n5-my-summer-holiday-l5', 'rdg-ja-n5-my-summer-holiday', 5, 2, '車で行きました。', 'くるま で いきました。', '[{"t":"車","r":"くるま"},{"t":"で"},{"t":"行","r":"い"},{"t":"きました"},{"t":"。"}]'::jsonb, 'We went by car.'),
  ('rdg-ja-n5-my-summer-holiday-l6', 'rdg-ja-n5-my-summer-holiday', 6, 2, '海は、とても大きかったです。', 'うみ わ、とても おおきかった です。', '[{"t":"海","r":"うみ"},{"t":"は"},{"t":"、"},{"t":"とても"},{"t":"大","r":"おお"},{"t":"きかった"},{"t":"です"},{"t":"。"}]'::jsonb, 'The sea was very big.'),
  ('rdg-ja-n5-my-summer-holiday-l7', 'rdg-ja-n5-my-summer-holiday', 7, 3, 'わたしは、海で泳ぎました。', 'わたし わ、うみ で およぎました。', '[{"t":"わたし"},{"t":"は"},{"t":"、"},{"t":"海","r":"うみ"},{"t":"で"},{"t":"泳","r":"およ"},{"t":"ぎました"},{"t":"。"}]'::jsonb, 'I swam in the sea.'),
  ('rdg-ja-n5-my-summer-holiday-l8', 'rdg-ja-n5-my-summer-holiday', 8, 3, '水は、少しつめたかったです。', 'みず わ、すこし つめたかった です。', '[{"t":"水","r":"みず"},{"t":"は"},{"t":"、"},{"t":"少","r":"すこ"},{"t":"し"},{"t":"つめたかった"},{"t":"です"},{"t":"。"}]'::jsonb, 'The water was a little cold.'),
  ('rdg-ja-n5-my-summer-holiday-l9', 'rdg-ja-n5-my-summer-holiday', 9, 3, '弟と、すなで山を作りました。', 'おとうと と、すな で やま お つくりました。', '[{"t":"弟","r":"おとうと"},{"t":"と"},{"t":"、"},{"t":"すな"},{"t":"で"},{"t":"山","r":"やま"},{"t":"を"},{"t":"作","r":"つく"},{"t":"りました"},{"t":"。"}]'::jsonb, 'I built a sand mountain with my little brother.'),
  ('rdg-ja-n5-my-summer-holiday-l10', 'rdg-ja-n5-my-summer-holiday', 10, 4, '夜は、花火を見ました。', 'よる わ、はなび お みました。', '[{"t":"夜","r":"よる"},{"t":"は"},{"t":"、"},{"t":"花火","r":"はなび"},{"t":"を"},{"t":"見","r":"み"},{"t":"ました"},{"t":"。"}]'::jsonb, 'At night, we watched fireworks.'),
  ('rdg-ja-n5-my-summer-holiday-l11', 'rdg-ja-n5-my-summer-holiday', 11, 4, '赤い花火も、青い花火もありました。', 'あかい はなび も、あおい はなび も ありました。', '[{"t":"赤","r":"あか"},{"t":"い"},{"t":"花火","r":"はなび"},{"t":"も"},{"t":"、"},{"t":"青","r":"あお"},{"t":"い"},{"t":"花火","r":"はなび"},{"t":"も"},{"t":"ありました"},{"t":"。"}]'::jsonb, 'There were red fireworks and blue ones.'),
  ('rdg-ja-n5-my-summer-holiday-l12', 'rdg-ja-n5-my-summer-holiday', 12, 4, 'とてもきれいでした。', 'とても きれい でした。', '[{"t":"とても"},{"t":"きれい"},{"t":"でした"},{"t":"。"}]'::jsonb, 'They were very beautiful.'),
  ('rdg-ja-n5-my-summer-holiday-l13', 'rdg-ja-n5-my-summer-holiday', 13, 5, 'なつやすみは、もうおわりました。', 'なつやすみ わ、もう おわりました。', '[{"t":"なつやすみ"},{"t":"は"},{"t":"、"},{"t":"もう"},{"t":"おわりました"},{"t":"。"}]'::jsonb, 'The summer holiday is over now.'),
  ('rdg-ja-n5-my-summer-holiday-l14', 'rdg-ja-n5-my-summer-holiday', 14, 5, '来年も、また海へ行きたいです。', 'らいねん も、また うみ え いきたい です。', '[{"t":"来年","r":"らいねん"},{"t":"も"},{"t":"、"},{"t":"また"},{"t":"海","r":"うみ"},{"t":"へ"},{"t":"行","r":"い"},{"t":"きたい"},{"t":"です"},{"t":"。"}]'::jsonb, 'Next year, I want to go to the sea again.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
