  ('rdg-ja-n5-cooking-dinner-l0', 'rdg-ja-n5-cooking-dinner', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n5-cooking-dinner-l1', 'rdg-ja-n5-cooking-dinner', 1, 0, '今日は、ばんごはんの話をします。', 'きょう わ、ばんごはん の はなし お します。', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"ばんごはん"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'Today I will talk about dinner.'),
  ('rdg-ja-n5-cooking-dinner-l2', 'rdg-ja-n5-cooking-dinner', 2, 1, 'わたしは、夜、ごはんを作ります。', 'わたし わ、よる、ごはん お つくります。', '[{"t":"わたし"},{"t":"は"},{"t":"、"},{"t":"夜","r":"よる"},{"t":"、"},{"t":"ごはん"},{"t":"を"},{"t":"作","r":"つく"},{"t":"ります"},{"t":"。"}]'::jsonb, 'In the evening, I make dinner.'),
  ('rdg-ja-n5-cooking-dinner-l3', 'rdg-ja-n5-cooking-dinner', 3, 1, '今日は、肉と野菜を使います。', 'きょう わ、にく と やさい お つかいます。', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"肉","r":"にく"},{"t":"と"},{"t":"野菜","r":"やさい"},{"t":"を"},{"t":"使","r":"つか"},{"t":"います"},{"t":"。"}]'::jsonb, 'Today I use meat and vegetables.'),
  ('rdg-ja-n5-cooking-dinner-l4', 'rdg-ja-n5-cooking-dinner', 4, 2, 'まず、手を洗います。', 'まず、て お あらいます。', '[{"t":"まず"},{"t":"、"},{"t":"手","r":"て"},{"t":"を"},{"t":"洗","r":"あら"},{"t":"います"},{"t":"。"}]'::jsonb, 'First, I wash my hands.'),
  ('rdg-ja-n5-cooking-dinner-l5', 'rdg-ja-n5-cooking-dinner', 5, 2, 'それから、野菜を小さく切ります。', 'それから、やさい お ちいさく きります。', '[{"t":"それから"},{"t":"、"},{"t":"野菜","r":"やさい"},{"t":"を"},{"t":"小","r":"ちい"},{"t":"さく"},{"t":"切","r":"き"},{"t":"ります"},{"t":"。"}]'::jsonb, 'Then I cut the vegetables small.'),
  ('rdg-ja-n5-cooking-dinner-l6', 'rdg-ja-n5-cooking-dinner', 6, 2, '肉も切ります。', 'にく も きります。', '[{"t":"肉","r":"にく"},{"t":"も"},{"t":"切","r":"き"},{"t":"ります"},{"t":"。"}]'::jsonb, 'I cut the meat too.'),
  ('rdg-ja-n5-cooking-dinner-l7', 'rdg-ja-n5-cooking-dinner', 7, 3, '次に、なべに水を入れます。', 'つぎ に、なべ に みず お いれます。', '[{"t":"次","r":"つぎ"},{"t":"に"},{"t":"、"},{"t":"なべ"},{"t":"に"},{"t":"水","r":"みず"},{"t":"を"},{"t":"入","r":"い"},{"t":"れます"},{"t":"。"}]'::jsonb, 'Next, I put water in the pot.'),
  ('rdg-ja-n5-cooking-dinner-l8', 'rdg-ja-n5-cooking-dinner', 8, 3, '火をつけて、少し待ちます。', 'ひ お つけて、すこし まちます。', '[{"t":"火","r":"ひ"},{"t":"を"},{"t":"つけて"},{"t":"、"},{"t":"少","r":"すこ"},{"t":"し"},{"t":"待","r":"ま"},{"t":"ちます"},{"t":"。"}]'::jsonb, 'I turn on the heat and wait a little.'),
  ('rdg-ja-n5-cooking-dinner-l9', 'rdg-ja-n5-cooking-dinner', 9, 3, '水があつくなると、肉を入れます。', 'みず が あつく なる と、にく お いれます。', '[{"t":"水","r":"みず"},{"t":"が"},{"t":"あつく"},{"t":"なる"},{"t":"と"},{"t":"、"},{"t":"肉","r":"にく"},{"t":"を"},{"t":"入","r":"い"},{"t":"れます"},{"t":"。"}]'::jsonb, 'When the water gets hot, I put in the meat.'),
  ('rdg-ja-n5-cooking-dinner-l10', 'rdg-ja-n5-cooking-dinner', 10, 3, '野菜も入れます。', 'やさい も いれます。', '[{"t":"野菜","r":"やさい"},{"t":"も"},{"t":"入","r":"い"},{"t":"れます"},{"t":"。"}]'::jsonb, 'I put in the vegetables too.'),
  ('rdg-ja-n5-cooking-dinner-l11', 'rdg-ja-n5-cooking-dinner', 11, 4, '二十分たつと、できあがりです。', 'にじゅっぷん たつ と、できあがり です。', '[{"t":"二十分","r":"にじゅっぷん"},{"t":"たつ"},{"t":"と"},{"t":"、"},{"t":"できあがり"},{"t":"です"},{"t":"。"}]'::jsonb, 'After twenty minutes, it is ready.'),
  ('rdg-ja-n5-cooking-dinner-l12', 'rdg-ja-n5-cooking-dinner', 12, 4, 'おいしいにおいがします。', 'おいしい におい が します。', '[{"t":"おいしい"},{"t":"におい"},{"t":"が"},{"t":"します"},{"t":"。"}]'::jsonb, 'It smells delicious.'),
  ('rdg-ja-n5-cooking-dinner-l13', 'rdg-ja-n5-cooking-dinner', 13, 4, 'いただきます。', 'いただきます。', '[{"t":"いただきます"},{"t":"。"}]'::jsonb, 'Let''s eat.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n5-cooking-dinner')
