ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n5-a-rainy-day-l0', 'rdg-ja-n5-a-rainy-day', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n5-a-rainy-day-l1', 'rdg-ja-n5-a-rainy-day', 1, 0, '雨の日の話をします。', 'あめ の ひ の はなし お します。', '[{"t":"雨","r":"あめ"},{"t":"の"},{"t":"日","r":"ひ"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'I will talk about a rainy day.'),
  ('rdg-ja-n5-a-rainy-day-l2', 'rdg-ja-n5-a-rainy-day', 2, 1, '今日は、朝から雨です。', 'きょう わ、あさ から あめ です。', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"朝","r":"あさ"},{"t":"から"},{"t":"雨","r":"あめ"},{"t":"です"},{"t":"。"}]'::jsonb, 'It has been raining since this morning.'),
  ('rdg-ja-n5-a-rainy-day-l3', 'rdg-ja-n5-a-rainy-day', 3, 1, 'そらは、少しくらいです。', 'そら わ、すこし くらい です。', '[{"t":"そら"},{"t":"は"},{"t":"、"},{"t":"少","r":"すこ"},{"t":"し"},{"t":"くらい"},{"t":"です"},{"t":"。"}]'::jsonb, 'The sky is a little dark.'),
  ('rdg-ja-n5-a-rainy-day-l4', 'rdg-ja-n5-a-rainy-day', 4, 1, 'わたしは、かさを持って出ました。', 'わたし わ、かさ お もって でました。', '[{"t":"わたし"},{"t":"は"},{"t":"、"},{"t":"かさ"},{"t":"を"},{"t":"持","r":"も"},{"t":"って"},{"t":"出","r":"で"},{"t":"ました"},{"t":"。"}]'::jsonb, 'I went out with an umbrella.'),
  ('rdg-ja-n5-a-rainy-day-l5', 'rdg-ja-n5-a-rainy-day', 5, 2, '道に、水がたくさんありました。', 'みち に、みず が たくさん ありました。', '[{"t":"道","r":"みち"},{"t":"に"},{"t":"、"},{"t":"水","r":"みず"},{"t":"が"},{"t":"たくさん"},{"t":"ありました"},{"t":"。"}]'::jsonb, 'There was a lot of water on the road.'),
  ('rdg-ja-n5-a-rainy-day-l6', 'rdg-ja-n5-a-rainy-day', 6, 2, 'くつが、ぬれました。', 'くつ が、ぬれました。', '[{"t":"くつ"},{"t":"が"},{"t":"、"},{"t":"ぬれました"},{"t":"。"}]'::jsonb, 'My shoes got wet.'),
  ('rdg-ja-n5-a-rainy-day-l7', 'rdg-ja-n5-a-rainy-day', 7, 2, '電車も、人が多かったです。', 'でんしゃ も、ひと が おおかった です。', '[{"t":"電車","r":"でんしゃ"},{"t":"も"},{"t":"、"},{"t":"人","r":"ひと"},{"t":"が"},{"t":"多","r":"おお"},{"t":"かったです"},{"t":"。"}]'::jsonb, 'The train was crowded too.'),
  ('rdg-ja-n5-a-rainy-day-l8', 'rdg-ja-n5-a-rainy-day', 8, 3, '学校で、友だちに会いました。', 'がっこう で、ともだち に あいました。', '[{"t":"学校","r":"がっこう"},{"t":"で"},{"t":"、"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"に"},{"t":"会","r":"あ"},{"t":"いました"},{"t":"。"}]'::jsonb, 'At school, I met my friend.'),
  ('rdg-ja-n5-a-rainy-day-l9', 'rdg-ja-n5-a-rainy-day', 9, 3, '友だちも、ぬれていました。', 'ともだち も、ぬれて いました。', '[{"t":"友","r":"とも"},{"t":"だち"},{"t":"も"},{"t":"、"},{"t":"ぬれて"},{"t":"いました"},{"t":"。"}]'::jsonb, 'My friend was wet too.'),
  ('rdg-ja-n5-a-rainy-day-l10', 'rdg-ja-n5-a-rainy-day', 10, 3, 'わたしたちは、わらいました。', 'わたしたち わ、わらいました。', '[{"t":"わたしたち"},{"t":"は"},{"t":"、"},{"t":"わらいました"},{"t":"。"}]'::jsonb, 'We laughed.'),
  ('rdg-ja-n5-a-rainy-day-l11', 'rdg-ja-n5-a-rainy-day', 11, 4, '家に帰って、あついお茶を飲みました。', 'いえ に かえって、あつい おちゃ お のみました。', '[{"t":"家","r":"いえ"},{"t":"に"},{"t":"帰","r":"かえ"},{"t":"って"},{"t":"、"},{"t":"あつい"},{"t":"お"},{"t":"茶","r":"ちゃ"},{"t":"を"},{"t":"飲","r":"の"},{"t":"みました"},{"t":"。"}]'::jsonb, 'I went home and drank hot tea.'),
  ('rdg-ja-n5-a-rainy-day-l12', 'rdg-ja-n5-a-rainy-day', 12, 4, 'そして、本を読みました。', 'そして、ほん お よみました。', '[{"t":"そして"},{"t":"、"},{"t":"本","r":"ほん"},{"t":"を"},{"t":"読","r":"よ"},{"t":"みました"},{"t":"。"}]'::jsonb, 'And I read a book.'),
  ('rdg-ja-n5-a-rainy-day-l13', 'rdg-ja-n5-a-rainy-day', 13, 4, 'わたしは、雨の音が好きです。', 'わたし わ、あめ の おと が すき です。', '[{"t":"わたし"},{"t":"は"},{"t":"、"},{"t":"雨","r":"あめ"},{"t":"の"},{"t":"音","r":"おと"},{"t":"が"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":"。"}]'::jsonb, 'I like the sound of rain.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n5-a-rainy-day')
ON CONFLICT (reading_id, index) DO NOTHING;

