INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n5-my-new-bag-l0', 'rdg-ja-n5-my-new-bag', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n5-my-new-bag-l1', 'rdg-ja-n5-my-new-bag', 1, 0, '新しいかばんの話をします。', 'あたらしい かばん の はなし お します。', '[{"t":"新","r":"あたら"},{"t":"しい"},{"t":"かばん"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'I will talk about my new bag.'),
  ('rdg-ja-n5-my-new-bag-l2', 'rdg-ja-n5-my-new-bag', 2, 1, '先週の土曜日に、店でかばんを買いました。', 'せんしゅう の どようび に、みせ で かばん お かいました。', '[{"t":"先週","r":"せんしゅう"},{"t":"の"},{"t":"土曜日","r":"どようび"},{"t":"に"},{"t":"、"},{"t":"店","r":"みせ"},{"t":"で"},{"t":"かばん"},{"t":"を"},{"t":"買","r":"か"},{"t":"いました"},{"t":"。"}]'::jsonb, 'Last Saturday, I bought a bag at a shop.'),
  ('rdg-ja-n5-my-new-bag-l3', 'rdg-ja-n5-my-new-bag', 3, 1, '前のかばんは、古かったです。', 'まえ の かばん わ、ふるかった です。', '[{"t":"前","r":"まえ"},{"t":"の"},{"t":"かばん"},{"t":"は"},{"t":"、"},{"t":"古","r":"ふる"},{"t":"かった"},{"t":"です"},{"t":"。"}]'::jsonb, 'My previous bag was worn out.'),
  ('rdg-ja-n5-my-new-bag-l4', 'rdg-ja-n5-my-new-bag', 4, 1, 'だから、新しいのがほしかったです。', 'だから、あたらしい の が ほしかった です。', '[{"t":"だから"},{"t":"、"},{"t":"新","r":"あたら"},{"t":"しい"},{"t":"の"},{"t":"が"},{"t":"ほしかった"},{"t":"です"},{"t":"。"}]'::jsonb, 'So I wanted a new one.'),
  ('rdg-ja-n5-my-new-bag-l5', 'rdg-ja-n5-my-new-bag', 5, 2, '新しいかばんは、青いです。', 'あたらしい かばん わ、あおい です。', '[{"t":"新","r":"あたら"},{"t":"しい"},{"t":"かばん"},{"t":"は"},{"t":"、"},{"t":"青","r":"あお"},{"t":"い"},{"t":"です"},{"t":"。"}]'::jsonb, 'The new bag is blue.'),
  ('rdg-ja-n5-my-new-bag-l6', 'rdg-ja-n5-my-new-bag', 6, 2, 'とても小さいです。', 'とても ちいさい です。', '[{"t":"とても"},{"t":"小","r":"ちい"},{"t":"さい"},{"t":"です"},{"t":"。"}]'::jsonb, 'It is very small.'),
  ('rdg-ja-n5-my-new-bag-l7', 'rdg-ja-n5-my-new-bag', 7, 2, 'でも、ポケットがたくさんあります。', 'でも、ポケット が たくさん あります。', '[{"t":"でも"},{"t":"、"},{"t":"ポケット"},{"t":"が"},{"t":"たくさん"},{"t":"あります"},{"t":"。"}]'::jsonb, 'But it has many pockets.'),
  ('rdg-ja-n5-my-new-bag-l8', 'rdg-ja-n5-my-new-bag', 8, 3, '本とノートを入れます。', 'ほん と ノート お いれます。', '[{"t":"本","r":"ほん"},{"t":"と"},{"t":"ノート"},{"t":"を"},{"t":"入","r":"い"},{"t":"れます"},{"t":"。"}]'::jsonb, 'I put books and a notebook in it.'),
  ('rdg-ja-n5-my-new-bag-l9', 'rdg-ja-n5-my-new-bag', 9, 3, 'それから、水も入れます。', 'それから、みず も いれます。', '[{"t":"それから"},{"t":"、"},{"t":"水","r":"みず"},{"t":"も"},{"t":"入","r":"い"},{"t":"れます"},{"t":"。"}]'::jsonb, 'And I put water in too.'),
  ('rdg-ja-n5-my-new-bag-l10', 'rdg-ja-n5-my-new-bag', 10, 3, 'とてもかるいです。', 'とても かるい です。', '[{"t":"とても"},{"t":"かるい"},{"t":"です"},{"t":"。"}]'::jsonb, 'It is very light.'),
  ('rdg-ja-n5-my-new-bag-l11', 'rdg-ja-n5-my-new-bag', 11, 4, 'わたしは、毎日このかばんを持って出かけます。', 'わたし わ、まいにち この かばん お もって でかけます。', '[{"t":"わたし"},{"t":"は"},{"t":"、"},{"t":"毎日","r":"まいにち"},{"t":"この"},{"t":"かばん"},{"t":"を"},{"t":"持","r":"も"},{"t":"って"},{"t":"出","r":"で"},{"t":"かけます"},{"t":"。"}]'::jsonb, 'I take this bag with me every day.'),
  ('rdg-ja-n5-my-new-bag-l12', 'rdg-ja-n5-my-new-bag', 12, 4, '友だちは、「いいですね」と言いました。', 'ともだち わ、「いい です ね」と いいました。', '[{"t":"友","r":"とも"},{"t":"だち"},{"t":"は"},{"t":"、「"},{"t":"いい"},{"t":"です"},{"t":"ね"},{"t":"」"},{"t":"と"},{"t":"言","r":"い"},{"t":"いました"},{"t":"。"}]'::jsonb, 'My friend said, "That''s nice."'),
  ('rdg-ja-n5-my-new-bag-l13', 'rdg-ja-n5-my-new-bag', 13, 4, '大切に使います。', 'たいせつ に つかいます。', '[{"t":"大切","r":"たいせつ"},{"t":"に"},{"t":"使","r":"つか"},{"t":"います"},{"t":"。"}]'::jsonb, 'I will use it with care.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
