-- N5 · n5-a-letter-to-a-friend · A letter to a friend
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n5-a-letter-to-a-friend', 'lang-ja', ll.id, 'n5-a-letter-to-a-friend', '友だちへの手紙', 'A letter to a friend', false, 24
