INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n5-a-letter-to-a-friend-l0', 'rdg-ja-n5-a-letter-to-a-friend', 0, 0, 'ゆきさん、お元気ですか。', 'ゆきさん、おげんき です か。', '[{"t":"ゆきさん"},{"t":"、"},{"t":"お"},{"t":"元気","r":"げんき"},{"t":"です"},{"t":"か"},{"t":"。"}]'::jsonb, 'Yuki, how are you?'),
  ('rdg-ja-n5-a-letter-to-a-friend-l1', 'rdg-ja-n5-a-letter-to-a-friend', 1, 0, 'わたしは、元気です。', 'わたし わ、げんき です。', '[{"t":"わたし"},{"t":"は"},{"t":"、"},{"t":"元気","r":"げんき"},{"t":"です"},{"t":"。"}]'::jsonb, 'I am well.'),
  ('rdg-ja-n5-a-letter-to-a-friend-l2', 'rdg-ja-n5-a-letter-to-a-friend', 2, 1, '手紙を書きます。', 'てがみ お かきます。', '[{"t":"手紙","r":"てがみ"},{"t":"を"},{"t":"書","r":"か"},{"t":"きます"},{"t":"。"}]'::jsonb, 'I''m writing to you.'),
  ('rdg-ja-n5-a-letter-to-a-friend-l3', 'rdg-ja-n5-a-letter-to-a-friend', 3, 1, 'ゆきさんに会いたいです。', 'ゆきさん に あいたい です。', '[{"t":"ゆきさん"},{"t":"に"},{"t":"会","r":"あ"},{"t":"いたい"},{"t":"です"},{"t":"。"}]'::jsonb, 'I want to see you.'),
  ('rdg-ja-n5-a-letter-to-a-friend-l4', 'rdg-ja-n5-a-letter-to-a-friend', 4, 1, '去年は、いっしょに学校へ行きましたね。', 'きょねん わ、いっしょ に がっこう え いきました ね。', '[{"t":"去年","r":"きょねん"},{"t":"は"},{"t":"、"},{"t":"いっしょ"},{"t":"に"},{"t":"学校","r":"がっこう"},{"t":"へ"},{"t":"行","r":"い"},{"t":"きました"},{"t":"ね"},{"t":"。"}]'::jsonb, 'Last year we went to school together.'),
  ('rdg-ja-n5-a-letter-to-a-friend-l5', 'rdg-ja-n5-a-letter-to-a-friend', 5, 2, '今、わたしは新しい町に住んでいます。', 'いま、わたし わ あたらしい まち に すんで います。', '[{"t":"今","r":"いま"},{"t":"、"},{"t":"わたし"},{"t":"は"},{"t":"新","r":"あたら"},{"t":"しい"},{"t":"町","r":"まち"},{"t":"に"},{"t":"住","r":"す"},{"t":"んで"},{"t":"います"},{"t":"。"}]'::jsonb, 'Now I live in a new town.'),
  ('rdg-ja-n5-a-letter-to-a-friend-l6', 'rdg-ja-n5-a-letter-to-a-friend', 6, 2, '家の近くに、大きいかわがあります。', 'いえ の ちかく に、おおきい かわ が あります。', '[{"t":"家","r":"いえ"},{"t":"の"},{"t":"近","r":"ちか"},{"t":"く"},{"t":"に"},{"t":"、"},{"t":"大","r":"おお"},{"t":"きい"},{"t":"かわ"},{"t":"が"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There is a big river near my house.'),
  ('rdg-ja-n5-a-letter-to-a-friend-l7', 'rdg-ja-n5-a-letter-to-a-friend', 7, 2, '毎日、かわのそばを歩きます。', 'まいにち、かわ の そば お あるきます。', '[{"t":"毎日","r":"まいにち"},{"t":"、"},{"t":"かわ"},{"t":"の"},{"t":"そば"},{"t":"を"},{"t":"歩","r":"ある"},{"t":"きます"},{"t":"。"}]'::jsonb, 'Every day I walk by the river.'),
  ('rdg-ja-n5-a-letter-to-a-friend-l8', 'rdg-ja-n5-a-letter-to-a-friend', 8, 3, '学校の友だちは、みんなやさしいです。', 'がっこう の ともだち わ、みんな やさしい です。', '[{"t":"学校","r":"がっこう"},{"t":"の"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"は"},{"t":"、"},{"t":"みんな"},{"t":"やさしい"},{"t":"です"},{"t":"。"}]'::jsonb, 'The friends at school are all kind.'),
  ('rdg-ja-n5-a-letter-to-a-friend-l9', 'rdg-ja-n5-a-letter-to-a-friend', 9, 3, 'でも、ゆきさんがいなくて、少しさびしいです。', 'でも、ゆきさん が いなくて、すこし さびしい です。', '[{"t":"でも"},{"t":"、"},{"t":"ゆきさん"},{"t":"が"},{"t":"いなくて"},{"t":"、"},{"t":"少","r":"すこ"},{"t":"し"},{"t":"さびしい"},{"t":"です"},{"t":"。"}]'::jsonb, 'But without you, I feel a little lonely.'),
  ('rdg-ja-n5-a-letter-to-a-friend-l10', 'rdg-ja-n5-a-letter-to-a-friend', 10, 4, 'ゆきさんは、今、何をしていますか。', 'ゆきさん わ、いま、なに お して います か。', '[{"t":"ゆきさん"},{"t":"は"},{"t":"、"},{"t":"今","r":"いま"},{"t":"、"},{"t":"何","r":"なに"},{"t":"を"},{"t":"して"},{"t":"います"},{"t":"か"},{"t":"。"}]'::jsonb, 'What are you doing now?'),
  ('rdg-ja-n5-a-letter-to-a-friend-l11', 'rdg-ja-n5-a-letter-to-a-friend', 11, 4, 'お返事を待っています。', 'おへんじ お まって います。', '[{"t":"お"},{"t":"返事","r":"へんじ"},{"t":"を"},{"t":"待","r":"ま"},{"t":"って"},{"t":"います"},{"t":"。"}]'::jsonb, 'I am waiting for your reply.'),
  ('rdg-ja-n5-a-letter-to-a-friend-l12', 'rdg-ja-n5-a-letter-to-a-friend', 12, 4, 'また、手紙を書いてください。', 'また、てがみ お かいて ください。', '[{"t":"また"},{"t":"、"},{"t":"手紙","r":"てがみ"},{"t":"を"},{"t":"書","r":"か"},{"t":"いて"},{"t":"ください"},{"t":"。"}]'::jsonb, 'Please write to me again.'),
  ('rdg-ja-n5-a-letter-to-a-friend-l13', 'rdg-ja-n5-a-letter-to-a-friend', 13, 4, 'さようなら。', 'さようなら。', '[{"t":"さようなら"},{"t":"。"}]'::jsonb, 'Goodbye.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
