FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N4'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n4-moving-to-a-new-city-l0', 'rdg-ja-n4-moving-to-a-new-city', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n4-moving-to-a-new-city-l1', 'rdg-ja-n4-moving-to-a-new-city', 1, 0, '先月、新しい町に来ました。', 'せんげつ、あたらしい まち に きました。', '[{"t":"先月","r":"せんげつ"},{"t":"、"},{"t":"新","r":"あたら"},{"t":"しい"},{"t":"町","r":"まち"},{"t":"に"},{"t":"来","r":"き"},{"t":"ました"},{"t":"。"}]'::jsonb, 'Last month, I came to a new city.'),
  ('rdg-ja-n4-moving-to-a-new-city-l2', 'rdg-ja-n4-moving-to-a-new-city', 2, 0, '今日は、新しい町の話をします。', 'きょう わ、あたらしい まち の はなし お します。', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"新","r":"あたら"},{"t":"しい"},{"t":"町","r":"まち"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'Today I will talk about my new city.'),
  ('rdg-ja-n4-moving-to-a-new-city-l3', 'rdg-ja-n4-moving-to-a-new-city', 3, 1, 'ひっこしの日は、朝から雨でした。', 'ひっこし の ひ わ、あさ から あめ でした。', '[{"t":"ひっこし"},{"t":"の"},{"t":"日","r":"ひ"},{"t":"は"},{"t":"、"},{"t":"朝","r":"あさ"},{"t":"から"},{"t":"雨","r":"あめ"},{"t":"でした"},{"t":"。"}]'::jsonb, 'On moving day, it rained from the morning.'),
  ('rdg-ja-n4-moving-to-a-new-city-l4', 'rdg-ja-n4-moving-to-a-new-city', 4, 1, '荷物は多くて、とても重かったです。', 'にもつ わ おおくて、とても おもかった です。', '[{"t":"荷物","r":"にもつ"},{"t":"は"},{"t":"多","r":"おお"},{"t":"くて"},{"t":"、"},{"t":"とても"},{"t":"重","r":"おも"},{"t":"かったです"},{"t":"。"}]'::jsonb, 'There were many bags, and they were very heavy.'),
  ('rdg-ja-n4-moving-to-a-new-city-l5', 'rdg-ja-n4-moving-to-a-new-city', 5, 1, '友だちが手伝ってくれました。', 'ともだち が てつだって くれました。', '[{"t":"友","r":"とも"},{"t":"だち"},{"t":"が"},{"t":"手伝","r":"てつだ"},{"t":"って"},{"t":"くれました"},{"t":"。"}]'::jsonb, 'A friend helped me.'),
  ('rdg-ja-n4-moving-to-a-new-city-l6', 'rdg-ja-n4-moving-to-a-new-city', 6, 2, '新しい町は、前の町より大きいです。', 'あたらしい まち わ、まえ の まち より おおきい です。', '[{"t":"新","r":"あたら"},{"t":"しい"},{"t":"町","r":"まち"},{"t":"は"},{"t":"、"},{"t":"前","r":"まえ"},{"t":"の"},{"t":"町","r":"まち"},{"t":"より"},{"t":"大","r":"おお"},{"t":"きい"},{"t":"です"},{"t":"。"}]'::jsonb, 'The new city is bigger than my old one.'),
  ('rdg-ja-n4-moving-to-a-new-city-l7', 'rdg-ja-n4-moving-to-a-new-city', 7, 2, '駅の近くに、店がたくさんあります。', 'えき の ちかく に、みせ が たくさん あります。', '[{"t":"駅","r":"えき"},{"t":"の"},{"t":"近","r":"ちか"},{"t":"く"},{"t":"に"},{"t":"、"},{"t":"店","r":"みせ"},{"t":"が"},{"t":"たくさん"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There are many shops near the station.'),
  ('rdg-ja-n4-moving-to-a-new-city-l8', 'rdg-ja-n4-moving-to-a-new-city', 8, 2, 'でも、道がわからなくて、よくまよいます。', 'でも、みち が わからなくて、よく まよいます。', '[{"t":"でも"},{"t":"、"},{"t":"道","r":"みち"},{"t":"が"},{"t":"わからなくて"},{"t":"、"},{"t":"よく"},{"t":"まよいます"},{"t":"。"}]'::jsonb, 'But I do not know the streets, so I often get lost.'),
  ('rdg-ja-n4-moving-to-a-new-city-l9', 'rdg-ja-n4-moving-to-a-new-city', 9, 3, 'はじめは、一人でさびしかったです。', 'はじめ わ、ひとり で さびしかった です。', '[{"t":"はじめ"},{"t":"は"},{"t":"、"},{"t":"一人","r":"ひとり"},{"t":"で"},{"t":"さびしかった"},{"t":"です"},{"t":"。"}]'::jsonb, 'At first, I felt lonely by myself.'),
  ('rdg-ja-n4-moving-to-a-new-city-l10', 'rdg-ja-n4-moving-to-a-new-city', 10, 3, 'となりの人に「こんにちは」と言いました。', 'となり の ひと に「こんにちわ」と いいました。', '[{"t":"となり"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"に"},{"t":"「"},{"t":"こんにちは"},{"t":"」"},{"t":"と"},{"t":"言","r":"い"},{"t":"いました"},{"t":"。"}]'::jsonb, 'I said "hello" to the person next door.'),
  ('rdg-ja-n4-moving-to-a-new-city-l11', 'rdg-ja-n4-moving-to-a-new-city', 11, 3, 'その人は、やさしく笑ってくれました。', 'その ひと わ、やさしく わらって くれました。', '[{"t":"その"},{"t":"人","r":"ひと"},{"t":"は"},{"t":"、"},{"t":"やさしく"},{"t":"笑","r":"わら"},{"t":"って"},{"t":"くれました"},{"t":"。"}]'::jsonb, 'That person smiled at me kindly.'),
  ('rdg-ja-n4-moving-to-a-new-city-l12', 'rdg-ja-n4-moving-to-a-new-city', 12, 4, '今は、近くの公園を歩くのが好きです。', 'いま わ、ちかく の こうえん お あるく の が すき です。', '[{"t":"今","r":"いま"},{"t":"は"},{"t":"、"},{"t":"近","r":"ちか"},{"t":"く"},{"t":"の"},{"t":"公園","r":"こうえん"},{"t":"を"},{"t":"歩","r":"ある"},{"t":"く"},{"t":"の"},{"t":"が"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":"。"}]'::jsonb, 'Now I like walking in the park nearby.'),
  ('rdg-ja-n4-moving-to-a-new-city-l13', 'rdg-ja-n4-moving-to-a-new-city', 13, 4, '少しずつ、この町が好きになってきました。', 'すこし ずつ、この まち が すき に なって きました。', '[{"t":"少","r":"すこ"},{"t":"し"},{"t":"ずつ"},{"t":"、"},{"t":"この"},{"t":"町","r":"まち"},{"t":"が"},{"t":"好","r":"す"},{"t":"き"},{"t":"に"},{"t":"なって"},{"t":"きました"},{"t":"。"}]'::jsonb, 'Little by little, I have come to like this city.'),
  ('rdg-ja-n4-moving-to-a-new-city-l14', 'rdg-ja-n4-moving-to-a-new-city', 14, 4, 'この町が、私の新しいふるさとです。', 'この まち が、わたし の あたらしい ふるさと です。', '[{"t":"この"},{"t":"町","r":"まち"},{"t":"が"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"の"},{"t":"新","r":"あたら"},{"t":"しい"},{"t":"ふるさと"},{"t":"です"},{"t":"。"}]'::jsonb, 'This city is my new hometown.'),
  ('rdg-ja-n4-moving-to-a-new-city-l15', 'rdg-ja-n4-moving-to-a-new-city', 15, 4, 'ありがとうございました。', 'ありがとうございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
