FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N4'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n4-my-part-time-job-l0', 'rdg-ja-n4-my-part-time-job', 0, 0, 'こんばんは。', 'こんばんわ。', '[{"t":"こんばんは"},{"t":"。"}]'::jsonb, 'Good evening.'),
  ('rdg-ja-n4-my-part-time-job-l1', 'rdg-ja-n4-my-part-time-job', 1, 0, '私は、先月からアルバイトをしています。', 'わたし わ、せんげつ から アルバイト お して います。', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"、"},{"t":"先月","r":"せんげつ"},{"t":"から"},{"t":"アルバイト"},{"t":"を"},{"t":"して"},{"t":"います"},{"t":"。"}]'::jsonb, 'I have had a part-time job since last month.'),
  ('rdg-ja-n4-my-part-time-job-l2', 'rdg-ja-n4-my-part-time-job', 2, 0, 'レストランで働いています。', 'レストラン で はたらいて います。', '[{"t":"レストラン"},{"t":"で"},{"t":"働","r":"はたら"},{"t":"いて"},{"t":"います"},{"t":"。"}]'::jsonb, 'I work at a restaurant.'),
  ('rdg-ja-n4-my-part-time-job-l3', 'rdg-ja-n4-my-part-time-job', 3, 1, '仕事は、夕方五時からです。', 'しごと わ、ゆうがた ごじ から です。', '[{"t":"仕事","r":"しごと"},{"t":"は"},{"t":"、"},{"t":"夕方","r":"ゆうがたごじ"},{"t":"五時"},{"t":"から"},{"t":"です"},{"t":"。"}]'::jsonb, 'My work starts at five in the evening.'),
  ('rdg-ja-n4-my-part-time-job-l4', 'rdg-ja-n4-my-part-time-job', 4, 1, 'まず、店の中をきれいにします。', 'まず、みせ の なか お きれいに します。', '[{"t":"まず"},{"t":"、"},{"t":"店","r":"みせ"},{"t":"の"},{"t":"中","r":"なか"},{"t":"を"},{"t":"きれいに"},{"t":"します"},{"t":"。"}]'::jsonb, 'First, I clean the inside of the shop.'),
  ('rdg-ja-n4-my-part-time-job-l5', 'rdg-ja-n4-my-part-time-job', 5, 1, 'それから、お客さんに水を出します。', 'それから、おきゃくさん に みず お だします。', '[{"t":"それから"},{"t":"、"},{"t":"お"},{"t":"客","r":"きゃく"},{"t":"さん"},{"t":"に"},{"t":"水","r":"みず"},{"t":"を"},{"t":"出","r":"だ"},{"t":"します"},{"t":"。"}]'::jsonb, 'Then I bring water to the customers.'),
  ('rdg-ja-n4-my-part-time-job-l6', 'rdg-ja-n4-my-part-time-job', 6, 2, 'はじめは、メニューを覚えるのが大変でした。', 'はじめ わ、メニュー お おぼえる の が たいへん でした。', '[{"t":"はじめ"},{"t":"は"},{"t":"、"},{"t":"メニュー"},{"t":"を"},{"t":"覚","r":"おぼ"},{"t":"える"},{"t":"の"},{"t":"が"},{"t":"大変","r":"たいへん"},{"t":"でした"},{"t":"。"}]'::jsonb, 'At first, learning the menu was hard.'),
  ('rdg-ja-n4-my-part-time-job-l7', 'rdg-ja-n4-my-part-time-job', 7, 2, '毎晩、家でなんども読みました。', 'まいばん、いえ で なんども よみました。', '[{"t":"毎晩","r":"まいばん"},{"t":"、"},{"t":"家","r":"いえ"},{"t":"で"},{"t":"なんども"},{"t":"読","r":"よ"},{"t":"みました"},{"t":"。"}]'::jsonb, 'Every night, I read it many times at home.'),
  ('rdg-ja-n4-my-part-time-job-l8', 'rdg-ja-n4-my-part-time-job', 8, 2, '今は、ほとんど覚えています。', 'いま わ、ほとんど おぼえて います。', '[{"t":"今","r":"いま"},{"t":"は"},{"t":"、"},{"t":"ほとんど"},{"t":"覚","r":"おぼ"},{"t":"えて"},{"t":"います"},{"t":"。"}]'::jsonb, 'Now I know almost all of it by heart.'),
  ('rdg-ja-n4-my-part-time-job-l9', 'rdg-ja-n4-my-part-time-job', 9, 3, 'てんちょうは、とても親切な人です。', 'てんちょう わ、とても しんせつな ひと です。', '[{"t":"てんちょう"},{"t":"は"},{"t":"、"},{"t":"とても"},{"t":"親切","r":"しんせつ"},{"t":"な"},{"t":"人","r":"ひと"},{"t":"です"},{"t":"。"}]'::jsonb, 'The manager is a very kind person.'),
  ('rdg-ja-n4-my-part-time-job-l10', 'rdg-ja-n4-my-part-time-job', 10, 3, 'まちがえても、おこりません。', 'まちがえても、おこりません。', '[{"t":"まちがえても"},{"t":"、"},{"t":"おこりません"},{"t":"。"}]'::jsonb, 'Even when I make a mistake, he does not get angry.'),
  ('rdg-ja-n4-my-part-time-job-l11', 'rdg-ja-n4-my-part-time-job', 11, 3, '「次は、がんばろう」と言ってくれます。', '「つぎ わ、がんばろう」と いって くれます。', '[{"t":"「"},{"t":"次","r":"つぎ"},{"t":"は"},{"t":"、"},{"t":"がんばろう"},{"t":"」"},{"t":"と"},{"t":"言","r":"い"},{"t":"って"},{"t":"くれます"},{"t":"。"}]'::jsonb, 'He says, "Let us do our best next time."'),
  ('rdg-ja-n4-my-part-time-job-l12', 'rdg-ja-n4-my-part-time-job', 12, 4, '疲れる日もありますが、楽しいです。', 'つかれる ひ も あります が、たのしい です。', '[{"t":"疲","r":"つか"},{"t":"れる"},{"t":"日","r":"ひ"},{"t":"も"},{"t":"あります"},{"t":"が"},{"t":"、"},{"t":"楽","r":"たの"},{"t":"しい"},{"t":"です"},{"t":"。"}]'::jsonb, 'There are tiring days, but it is fun.'),
  ('rdg-ja-n4-my-part-time-job-l13', 'rdg-ja-n4-my-part-time-job', 13, 4, 'お客さんが「おいしかった」と言うと、うれしいです。', 'おきゃくさん が「おいしかった」と いう と、うれしい です。', '[{"t":"お"},{"t":"客","r":"きゃく"},{"t":"さん"},{"t":"が"},{"t":"「"},{"t":"おいしかった"},{"t":"」"},{"t":"と"},{"t":"言","r":"い"},{"t":"う"},{"t":"と"},{"t":"、"},{"t":"うれしい"},{"t":"です"},{"t":"。"}]'::jsonb, 'When a customer says "it was delicious," I am happy.'),
  ('rdg-ja-n4-my-part-time-job-l14', 'rdg-ja-n4-my-part-time-job', 14, 4, 'このお金で、いつか旅行に行きたいです。', 'この おかね で、いつか りょこう に いきたい です。', '[{"t":"この"},{"t":"お"},{"t":"金","r":"かね"},{"t":"で"},{"t":"、"},{"t":"いつか"},{"t":"旅行","r":"りょこう"},{"t":"に"},{"t":"行","r":"い"},{"t":"きたい"},{"t":"です"},{"t":"。"}]'::jsonb, 'With this money, I want to go on a trip someday.'),
  ('rdg-ja-n4-my-part-time-job-l15', 'rdg-ja-n4-my-part-time-job', 15, 4, 'ありがとうございました。', 'ありがとうございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n4-my-part-time-job')
