-- N4 · n4-summer-festival · The summer festival
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n4-summer-festival', 'lang-ja', ll.id, 'n4-summer-festival', '夏のお祭り', 'The summer festival', false, 32
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N4'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n4-summer-festival-l0', 'rdg-ja-n4-summer-festival', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n4-summer-festival-l1', 'rdg-ja-n4-summer-festival', 1, 0, '先週の土曜日、夏のお祭りに行きました。', 'せんしゅう の どようび、なつ の おまつり に いきました。', '[{"t":"先週","r":"せんしゅう"},{"t":"の"},{"t":"土曜日","r":"どようび"},{"t":"、"},{"t":"夏","r":"なつ"},{"t":"の"},{"t":"お"},{"t":"祭","r":"まつ"},{"t":"り"},{"t":"に"},{"t":"行","r":"い"},{"t":"きました"},{"t":"。"}]'::jsonb, 'Last Saturday, I went to a summer festival.'),
  ('rdg-ja-n4-summer-festival-l2', 'rdg-ja-n4-summer-festival', 2, 0, 'とても楽しい一日でした。', 'とても たのしい いちにち でした。', '[{"t":"とても"},{"t":"楽","r":"たの"},{"t":"しい"},{"t":"一日","r":"いちにち"},{"t":"でした"},{"t":"。"}]'::jsonb, 'It was a very fun day.'),
  ('rdg-ja-n4-summer-festival-l3', 'rdg-ja-n4-summer-festival', 3, 1, '夕方、友だちと駅で会いました。', 'ゆうがた、ともだち と えき で あいました。', '[{"t":"夕方","r":"ゆうがた"},{"t":"、"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"と"},{"t":"駅","r":"えき"},{"t":"で"},{"t":"会","r":"あ"},{"t":"いました"},{"t":"。"}]'::jsonb, 'In the evening, I met my friends at the station.'),
  ('rdg-ja-n4-summer-festival-l4', 'rdg-ja-n4-summer-festival', 4, 1, 'みんなゆかたを着ていました。', 'みんな ゆかた お きて いました。', '[{"t":"みんな"},{"t":"ゆかた"},{"t":"を"},{"t":"着","r":"き"},{"t":"て"},{"t":"いました"},{"t":"。"}]'::jsonb, 'Everyone was wearing a yukata.'),
  ('rdg-ja-n4-summer-festival-l5', 'rdg-ja-n4-summer-festival', 5, 1, '私も、はじめて着ました。', 'わたし も、はじめて きました。', '[{"t":"私","r":"わたし"},{"t":"も"},{"t":"、"},{"t":"はじめて"},{"t":"着","r":"き"},{"t":"ました"},{"t":"。"}]'::jsonb, 'I wore one for the first time too.'),
  ('rdg-ja-n4-summer-festival-l6', 'rdg-ja-n4-summer-festival', 6, 2, '道には、たくさんの店が出ていました。', 'みち に わ、たくさん の みせ が でて いました。', '[{"t":"道","r":"みち"},{"t":"に"},{"t":"は"},{"t":"、"},{"t":"たくさん"},{"t":"の"},{"t":"店","r":"みせ"},{"t":"が"},{"t":"出","r":"で"},{"t":"て"},{"t":"いました"},{"t":"。"}]'::jsonb, 'Many stalls lined the street.'),
  ('rdg-ja-n4-summer-festival-l7', 'rdg-ja-n4-summer-festival', 7, 2, 'たこやきと、かきごおりを食べました。', 'たこやき と、かきごおり お たべました。', '[{"t":"たこやき"},{"t":"と"},{"t":"、"},{"t":"かきごおり"},{"t":"を"},{"t":"食","r":"た"},{"t":"べました"},{"t":"。"}]'::jsonb, 'I ate takoyaki and shaved ice.'),
  ('rdg-ja-n4-summer-festival-l8', 'rdg-ja-n4-summer-festival', 8, 2, 'かきごおりは冷たくて、おいしかったです。', 'かきごおり わ つめたくて、おいしかった です。', '[{"t":"かきごおり"},{"t":"は"},{"t":"冷","r":"つめ"},{"t":"たくて"},{"t":"、"},{"t":"おいしかった"},{"t":"です"},{"t":"。"}]'::jsonb, 'The shaved ice was cold and delicious.'),
  ('rdg-ja-n4-summer-festival-l9', 'rdg-ja-n4-summer-festival', 9, 3, '夜になって、花火が始まりました。', 'よる に なって、はなび が はじまりました。', '[{"t":"夜","r":"よる"},{"t":"に"},{"t":"なって"},{"t":"、"},{"t":"花火","r":"はなび"},{"t":"が"},{"t":"始","r":"はじ"},{"t":"まりました"},{"t":"。"}]'::jsonb, 'When night came, the fireworks began.'),
  ('rdg-ja-n4-summer-festival-l10', 'rdg-ja-n4-summer-festival', 10, 3, '大きな音と、きれいな光。', 'おおきな おと と、きれいな ひかり。', '[{"t":"大","r":"おお"},{"t":"きな"},{"t":"音","r":"おと"},{"t":"と"},{"t":"、"},{"t":"きれいな"},{"t":"光","r":"ひかり"},{"t":"。"}]'::jsonb, 'A loud sound and beautiful light.'),
  ('rdg-ja-n4-summer-festival-l11', 'rdg-ja-n4-summer-festival', 11, 3, '空を見て、みんな「わあ」と言いました。', 'そら お みて、みんな「わあ」と いいました。', '[{"t":"空","r":"そら"},{"t":"を"},{"t":"見","r":"み"},{"t":"て"},{"t":"、"},{"t":"みんな"},{"t":"「"},{"t":"わあ"},{"t":"」"},{"t":"と"},{"t":"言","r":"い"},{"t":"いました"},{"t":"。"}]'::jsonb, 'Looking at the sky, everyone said "wow."'),
  ('rdg-ja-n4-summer-festival-l12', 'rdg-ja-n4-summer-festival', 12, 4, '帰り道、あしが少し痛かったです。', 'かえりみち、あし が すこし いたかった です。', '[{"t":"帰","r":"かえ"},{"t":"り"},{"t":"道","r":"みち"},{"t":"、"},{"t":"あし"},{"t":"が"},{"t":"少","r":"すこ"},{"t":"し"},{"t":"痛","r":"いた"},{"t":"かったです"},{"t":"。"}]'::jsonb, 'On the way home, my feet hurt a little.'),
  ('rdg-ja-n4-summer-festival-l13', 'rdg-ja-n4-summer-festival', 13, 4, 'でも、気持ちはとても楽しかったです。', 'でも、きもち わ とても たのしかった です。', '[{"t":"でも"},{"t":"、"},{"t":"気持","r":"きも"},{"t":"ち"},{"t":"は"},{"t":"とても"},{"t":"楽","r":"たの"},{"t":"しかった"},{"t":"です"},{"t":"。"}]'::jsonb, 'But I was in a really happy mood.'),
  ('rdg-ja-n4-summer-festival-l14', 'rdg-ja-n4-summer-festival', 14, 4, '来年も、また行きたいです。', 'らいねん も、また いきたい です。', '[{"t":"来年","r":"らいねん"},{"t":"も"},{"t":"、"},{"t":"また"},{"t":"行","r":"い"},{"t":"きたい"},{"t":"です"},{"t":"。"}]'::jsonb, 'I want to go again next year too.'),
  ('rdg-ja-n4-summer-festival-l15', 'rdg-ja-n4-summer-festival', 15, 4, 'ありがとうございました。', 'ありがとうございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n4-summer-festival')
ON CONFLICT (reading_id, index) DO NOTHING;

