-- N4 · n4-learning-to-swim · I learned to swim
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n4-learning-to-swim', 'lang-ja', ll.id, 'n4-learning-to-swim', '泳げるようになった', 'I learned to swim', false, 33
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N4'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n4-learning-to-swim-l0', 'rdg-ja-n4-learning-to-swim', 0, 0, 'みなさん、はじめまして。', 'みなさん、はじめまして。', '[{"t":"みなさん"},{"t":"、"},{"t":"はじめまして"},{"t":"。"}]'::jsonb, 'Hello, everyone, nice to meet you.'),
  ('rdg-ja-n4-learning-to-swim-l1', 'rdg-ja-n4-learning-to-swim', 1, 0, '去年まで、私は泳げませんでした。', 'きょねん まで、わたし わ およげません でした。', '[{"t":"去年","r":"きょねん"},{"t":"まで"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"は"},{"t":"泳","r":"およ"},{"t":"げ"},{"t":"ませんでした"},{"t":"。"}]'::jsonb, 'Until last year, I could not swim.'),
  ('rdg-ja-n4-learning-to-swim-l2', 'rdg-ja-n4-learning-to-swim', 2, 0, '今日は、泳げるようになった話をします。', 'きょう わ、およげる よう に なった はなし お します。', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"泳","r":"およ"},{"t":"げる"},{"t":"よう"},{"t":"に"},{"t":"なった"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'Today I will tell you how I learned to swim.'),
  ('rdg-ja-n4-learning-to-swim-l3', 'rdg-ja-n4-learning-to-swim', 3, 1, '子どものころから、水が少しこわかったのです。', 'こども の ころ から、みず が すこし こわかった の です。', '[{"t":"子","r":"こ"},{"t":"ども"},{"t":"の"},{"t":"ころ"},{"t":"から"},{"t":"、"},{"t":"水","r":"みず"},{"t":"が"},{"t":"少","r":"すこ"},{"t":"し"},{"t":"こわかった"},{"t":"のです"},{"t":"。"}]'::jsonb, 'Ever since I was a child, I had been a little afraid of water.'),
  ('rdg-ja-n4-learning-to-swim-l4', 'rdg-ja-n4-learning-to-swim', 4, 1, '顔を水に入れることもできませんでした。', 'かお お みず に いれる こと も できません でした。', '[{"t":"顔","r":"かお"},{"t":"を"},{"t":"水","r":"みず"},{"t":"に"},{"t":"入","r":"い"},{"t":"れる"},{"t":"こと"},{"t":"も"},{"t":"できません"},{"t":"でした"},{"t":"。"}]'::jsonb, 'I could not even put my face in the water.'),
  ('rdg-ja-n4-learning-to-swim-l5', 'rdg-ja-n4-learning-to-swim', 5, 1, 'でも、夏に友だちと海へ行きたかったのです。', 'でも、なつ に ともだち と うみ え いきたかった の です。', '[{"t":"でも"},{"t":"、"},{"t":"夏","r":"なつ"},{"t":"に"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"と"},{"t":"海","r":"うみ"},{"t":"へ"},{"t":"行","r":"い"},{"t":"き"},{"t":"たかった"},{"t":"のです"},{"t":"。"}]'::jsonb, 'But I wanted to go to the sea with friends in summer.'),
  ('rdg-ja-n4-learning-to-swim-l6', 'rdg-ja-n4-learning-to-swim', 6, 2, 'それで、町のプールに通い始めました。', 'それで、まち の プール に かよい はじめました。', '[{"t":"それで"},{"t":"、"},{"t":"町","r":"まち"},{"t":"の"},{"t":"プール"},{"t":"に"},{"t":"通","r":"かよ"},{"t":"い"},{"t":"始","r":"はじ"},{"t":"めました"},{"t":"。"}]'::jsonb, 'So I started going to the town pool.'),
  ('rdg-ja-n4-learning-to-swim-l7', 'rdg-ja-n4-learning-to-swim', 7, 2, '先生は、わかい女の人でした。', 'せんせい わ、わかい おんな の ひと でした。', '[{"t":"先生","r":"せんせい"},{"t":"は"},{"t":"、"},{"t":"わかい"},{"t":"女","r":"おんな"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"でした"},{"t":"。"}]'::jsonb, 'The teacher was a young woman.'),
  ('rdg-ja-n4-learning-to-swim-l8', 'rdg-ja-n4-learning-to-swim', 8, 2, '「ゆっくりでいいですよ」と言ってくれました。', '「ゆっくり で いい です よ」と いって くれました。', '[{"t":"「"},{"t":"ゆっくり"},{"t":"で"},{"t":"いい"},{"t":"です"},{"t":"よ"},{"t":"」"},{"t":"と"},{"t":"言","r":"い"},{"t":"って"},{"t":"くれました"},{"t":"。"}]'::jsonb, 'She told me, "Slowly is fine."'),
  ('rdg-ja-n4-learning-to-swim-l9', 'rdg-ja-n4-learning-to-swim', 9, 3, 'しばらくして、やっと顔を水に入れられました。', 'しばらく して、やっと かお お みず に いれられました。', '[{"t":"しばらく"},{"t":"して"},{"t":"、"},{"t":"やっと"},{"t":"顔","r":"かお"},{"t":"を"},{"t":"水","r":"みず"},{"t":"に"},{"t":"入","r":"い"},{"t":"れられました"},{"t":"。"}]'::jsonb, 'After a while, I could finally put my face in the water.'),
  ('rdg-ja-n4-learning-to-swim-l10', 'rdg-ja-n4-learning-to-swim', 10, 3, '三か月目に、十メートル泳げました。', 'さんかげつめ に、じゅう メートル およげました。', '[{"t":"三","r":"さん"},{"t":"か"},{"t":"月目","r":"げつめ"},{"t":"に"},{"t":"、"},{"t":"十","r":"じゅう"},{"t":"メートル"},{"t":"泳","r":"およ"},{"t":"げました"},{"t":"。"}]'::jsonb, 'In the third month, I swam ten metres.'),
  ('rdg-ja-n4-learning-to-swim-l11', 'rdg-ja-n4-learning-to-swim', 11, 3, 'うれしくて、プールで大きな声を出しました。', 'うれしくて、プール で おおきな こえ お だしました。', '[{"t":"うれしくて"},{"t":"、"},{"t":"プール"},{"t":"で"},{"t":"大","r":"おお"},{"t":"きな"},{"t":"声","r":"こえ"},{"t":"を"},{"t":"出","r":"だ"},{"t":"しました"},{"t":"。"}]'::jsonb, 'I was so happy that I shouted in the pool.'),
  ('rdg-ja-n4-learning-to-swim-l12', 'rdg-ja-n4-learning-to-swim', 12, 4, '先週、みんなで海に行きました。', 'せんしゅう、みんな で うみ に いきました。', '[{"t":"先週","r":"せんしゅう"},{"t":"、"},{"t":"みんな"},{"t":"で"},{"t":"海","r":"うみ"},{"t":"に"},{"t":"行","r":"い"},{"t":"きました"},{"t":"。"}]'::jsonb, 'Last week, we all went to the sea.'),
  ('rdg-ja-n4-learning-to-swim-l13', 'rdg-ja-n4-learning-to-swim', 13, 4, '私は、友だちと一緒に泳ぎました。', 'わたし わ、ともだち と いっしょ に およぎました。', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"、"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"と"},{"t":"一緒","r":"いっしょ"},{"t":"に"},{"t":"泳","r":"およ"},{"t":"ぎました"},{"t":"。"}]'::jsonb, 'I swam together with my friends.'),
  ('rdg-ja-n4-learning-to-swim-l14', 'rdg-ja-n4-learning-to-swim', 14, 4, 'できないことも、続ければできるようになります。', 'できない こと も、つづければ できる よう に なります。', '[{"t":"できない"},{"t":"こと"},{"t":"も"},{"t":"、"},{"t":"続","r":"つづ"},{"t":"ければ"},{"t":"できる"},{"t":"よう"},{"t":"に"},{"t":"なります"},{"t":"。"}]'::jsonb, 'Even things you cannot do, you can learn to do if you keep at it.'),
  ('rdg-ja-n4-learning-to-swim-l15', 'rdg-ja-n4-learning-to-swim', 15, 4, 'ありがとうございました。', 'ありがとうございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n4-learning-to-swim')
ON CONFLICT (reading_id, index) DO NOTHING;

