SELECT 'crq-rdg-ja-n4-learning-to-swim', 'lang-ja', 'readings', 'rdg-ja-n4-learning-to-swim', 'create', '{"code":"n4-learning-to-swim","level":"N4"}'::jsonb, 'ai', 2, 'pending'
