-- N4 · n4-day-i-lost-my-wallet · The day I lost my wallet
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n4-day-i-lost-my-wallet', 'lang-ja', ll.id, 'n4-day-i-lost-my-wallet', 'さいふをなくした日', 'The day I lost my wallet', false, 34
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N4'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n4-day-i-lost-my-wallet-l0', 'rdg-ja-n4-day-i-lost-my-wallet', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n4-day-i-lost-my-wallet-l1', 'rdg-ja-n4-day-i-lost-my-wallet', 1, 0, '先月、さいふをなくしました。', 'せんげつ、さいふ お なくしました。', '[{"t":"先月","r":"せんげつ"},{"t":"、"},{"t":"さいふ"},{"t":"を"},{"t":"なくしました"},{"t":"。"}]'::jsonb, 'Last month, I lost my wallet.'),
  ('rdg-ja-n4-day-i-lost-my-wallet-l2', 'rdg-ja-n4-day-i-lost-my-wallet', 2, 0, 'そのときの話をします。', 'その とき の はなし お します。', '[{"t":"その"},{"t":"とき"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'I will tell you about that time.'),
  ('rdg-ja-n4-day-i-lost-my-wallet-l3', 'rdg-ja-n4-day-i-lost-my-wallet', 3, 1, '昼ごはんのあと、店を出ました。', 'ひるごはん の あと、みせ お でました。', '[{"t":"昼","r":"ひる"},{"t":"ごはん"},{"t":"の"},{"t":"あと"},{"t":"、"},{"t":"店","r":"みせ"},{"t":"を"},{"t":"出","r":"で"},{"t":"ました"},{"t":"。"}]'::jsonb, 'After lunch, I left the shop.'),
  ('rdg-ja-n4-day-i-lost-my-wallet-l4', 'rdg-ja-n4-day-i-lost-my-wallet', 4, 1, '駅に着いたとき、かばんが軽いと思いました。', 'えき に ついた とき、かばん が かるい と おもいました。', '[{"t":"駅","r":"えき"},{"t":"に"},{"t":"着","r":"つ"},{"t":"いた"},{"t":"とき"},{"t":"、"},{"t":"かばん"},{"t":"が"},{"t":"軽","r":"かる"},{"t":"い"},{"t":"と"},{"t":"思","r":"おも"},{"t":"いました"},{"t":"。"}]'::jsonb, 'When I reached the station, I thought my bag felt light.'),
  ('rdg-ja-n4-day-i-lost-my-wallet-l5', 'rdg-ja-n4-day-i-lost-my-wallet', 5, 1, 'さいふが、どこにもありませんでした。', 'さいふ が、どこ に も ありません でした。', '[{"t":"さいふ"},{"t":"が"},{"t":"、"},{"t":"どこ"},{"t":"に"},{"t":"も"},{"t":"ありません"},{"t":"でした"},{"t":"。"}]'::jsonb, 'My wallet was nowhere to be found.'),
  ('rdg-ja-n4-day-i-lost-my-wallet-l6', 'rdg-ja-n4-day-i-lost-my-wallet', 6, 2, 'あたまが真っ白になりました。', 'あたま が まっしろ に なりました。', '[{"t":"あたま"},{"t":"が"},{"t":"真","r":"ま"},{"t":"っ"},{"t":"白","r":"しろ"},{"t":"に"},{"t":"なりました"},{"t":"。"}]'::jsonb, 'My mind went blank.'),
  ('rdg-ja-n4-day-i-lost-my-wallet-l7', 'rdg-ja-n4-day-i-lost-my-wallet', 7, 2, 'カードも、お金も、入っていたからです。', 'カード も、おかね も、はいって いた から です。', '[{"t":"カード"},{"t":"も"},{"t":"、"},{"t":"お"},{"t":"金","r":"かね"},{"t":"も"},{"t":"、"},{"t":"入","r":"はい"},{"t":"って"},{"t":"いた"},{"t":"から"},{"t":"です"},{"t":"。"}]'::jsonb, 'It was because my cards and money were inside.'),
  ('rdg-ja-n4-day-i-lost-my-wallet-l8', 'rdg-ja-n4-day-i-lost-my-wallet', 8, 2, 'まず、さっきの店まで走って戻りました。', 'まず、さっき の みせ まで はしって もどりました。', '[{"t":"まず"},{"t":"、"},{"t":"さっき"},{"t":"の"},{"t":"店","r":"みせ"},{"t":"まで"},{"t":"走","r":"はし"},{"t":"って"},{"t":"戻","r":"もど"},{"t":"りました"},{"t":"。"}]'::jsonb, 'First, I ran back to the shop I had just left.'),
  ('rdg-ja-n4-day-i-lost-my-wallet-l9', 'rdg-ja-n4-day-i-lost-my-wallet', 9, 3, 'でも、店の人は「ありません」と言いました。', 'でも、みせ の ひと わ「ありません」と いいました。', '[{"t":"でも"},{"t":"、"},{"t":"店","r":"みせ"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"は"},{"t":"「"},{"t":"ありません"},{"t":"」"},{"t":"と"},{"t":"言","r":"い"},{"t":"いました"},{"t":"。"}]'::jsonb, 'But the shop staff said, "We do not have it."'),
  ('rdg-ja-n4-day-i-lost-my-wallet-l10', 'rdg-ja-n4-day-i-lost-my-wallet', 10, 3, 'それで、駅の前の交番に行きました。', 'それで、えき の まえ の こうばん に いきました。', '[{"t":"それで"},{"t":"、"},{"t":"駅","r":"えき"},{"t":"の"},{"t":"前","r":"まえ"},{"t":"の"},{"t":"交番","r":"こうばん"},{"t":"に"},{"t":"行","r":"い"},{"t":"きました"},{"t":"。"}]'::jsonb, 'So I went to the police box in front of the station.'),
  ('rdg-ja-n4-day-i-lost-my-wallet-l11', 'rdg-ja-n4-day-i-lost-my-wallet', 11, 3, '警察の人は、ていねいに話を聞いてくれました。', 'けいさつ の ひと わ、ていねいに はなし お きいて くれました。', '[{"t":"警察","r":"けいさつ"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"は"},{"t":"、"},{"t":"ていねいに"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"聞","r":"き"},{"t":"いて"},{"t":"くれました"},{"t":"。"}]'::jsonb, 'The police officer listened to me politely.'),
  ('rdg-ja-n4-day-i-lost-my-wallet-l12', 'rdg-ja-n4-day-i-lost-my-wallet', 12, 4, '三日後に、電話がありました。', 'みっか ご に、でんわ が ありました。', '[{"t":"三日","r":"みっかご"},{"t":"後"},{"t":"に"},{"t":"、"},{"t":"電話","r":"でんわ"},{"t":"が"},{"t":"ありました"},{"t":"。"}]'::jsonb, 'Three days later, I got a phone call.'),
  ('rdg-ja-n4-day-i-lost-my-wallet-l13', 'rdg-ja-n4-day-i-lost-my-wallet', 13, 4, '「さいふが見つかりましたよ」と言われました。', '「さいふ が みつかりました よ」と いわれました。', '[{"t":"「"},{"t":"さいふ"},{"t":"が"},{"t":"見","r":"み"},{"t":"つかりました"},{"t":"よ"},{"t":"」"},{"t":"と"},{"t":"言","r":"い"},{"t":"われました"},{"t":"。"}]'::jsonb, 'I was told, "Your wallet has been found."'),
  ('rdg-ja-n4-day-i-lost-my-wallet-l14', 'rdg-ja-n4-day-i-lost-my-wallet', 14, 4, 'お金は、全部ありました。', 'おかね わ、ぜんぶ ありました。', '[{"t":"お"},{"t":"金","r":"かね"},{"t":"は"},{"t":"、"},{"t":"全部","r":"ぜんぶ"},{"t":"ありました"},{"t":"。"}]'::jsonb, 'All of the money was there.'),
  ('rdg-ja-n4-day-i-lost-my-wallet-l15', 'rdg-ja-n4-day-i-lost-my-wallet', 15, 4, '見つけてくれた人に、心からかんしゃしています。', 'みつけて くれた ひと に、こころ から かんしゃ して います。', '[{"t":"見","r":"み"},{"t":"つけて"},{"t":"くれた"},{"t":"人","r":"ひと"},{"t":"に"},{"t":"、"},{"t":"心","r":"こころ"},{"t":"から"},{"t":"かんしゃ"},{"t":"して"},{"t":"います"},{"t":"。"}]'::jsonb, 'I am truly grateful to the person who found it.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
