INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n4-my-grandmother-l0', 'rdg-ja-n4-my-grandmother', 0, 0, 'みなさん、お元気ですか。', 'みなさん、おげんき です か。', '[{"t":"みなさん"},{"t":"、"},{"t":"お"},{"t":"元気","r":"げんき"},{"t":"です"},{"t":"か"},{"t":"。"}]'::jsonb, 'How is everyone?'),
  ('rdg-ja-n4-my-grandmother-l1', 'rdg-ja-n4-my-grandmother', 1, 0, '今日は、おばあちゃんの話をします。', 'きょう わ、おばあちゃん の はなし お します。', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"おばあちゃん"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'Today I will talk about my grandmother.'),
  ('rdg-ja-n4-my-grandmother-l2', 'rdg-ja-n4-my-grandmother', 2, 0, '私の大切な人です。', 'わたし の たいせつな ひと です。', '[{"t":"私","r":"わたし"},{"t":"の"},{"t":"大切","r":"たいせつ"},{"t":"な"},{"t":"人","r":"ひと"},{"t":"です"},{"t":"。"}]'::jsonb, 'She is an important person to me.'),
  ('rdg-ja-n4-my-grandmother-l3', 'rdg-ja-n4-my-grandmother', 3, 1, 'おばあちゃんは、山の近くの家に住んでいます。', 'おばあちゃん わ、やま の ちかく の いえ に すんで います。', '[{"t":"おばあちゃん"},{"t":"は"},{"t":"、"},{"t":"山","r":"やま"},{"t":"の"},{"t":"近","r":"ちか"},{"t":"く"},{"t":"の"},{"t":"家","r":"いえ"},{"t":"に"},{"t":"住","r":"す"},{"t":"んで"},{"t":"います"},{"t":"。"}]'::jsonb, 'My grandmother lives in a house near the mountains.'),
  ('rdg-ja-n4-my-grandmother-l4', 'rdg-ja-n4-my-grandmother', 4, 1, '年は、もう八十歳です。', 'とし わ、もう はちじゅっさい です。', '[{"t":"年","r":"とし"},{"t":"は"},{"t":"、"},{"t":"もう"},{"t":"八十歳","r":"はちじゅっさい"},{"t":"です"},{"t":"。"}]'::jsonb, 'She is already eighty years old.'),
  ('rdg-ja-n4-my-grandmother-l5', 'rdg-ja-n4-my-grandmother', 5, 1, 'でも、毎朝、早く起きてはたけに行きます。', 'でも、まいあさ、はやく おきて はたけ に いきます。', '[{"t":"でも"},{"t":"、"},{"t":"毎朝","r":"まいあさ"},{"t":"、"},{"t":"早","r":"はや"},{"t":"く"},{"t":"起","r":"お"},{"t":"きて"},{"t":"はたけ"},{"t":"に"},{"t":"行","r":"い"},{"t":"きます"},{"t":"。"}]'::jsonb, 'But every morning she wakes early and goes to the field.'),
  ('rdg-ja-n4-my-grandmother-l6', 'rdg-ja-n4-my-grandmother', 6, 2, '夏休みには、よくおばあちゃんの家に泊まりました。', 'なつやすみ に わ、よく おばあちゃん の いえ に とまりました。', '[{"t":"夏休","r":"なつやす"},{"t":"み"},{"t":"に"},{"t":"は"},{"t":"、"},{"t":"よく"},{"t":"おばあちゃん"},{"t":"の"},{"t":"家","r":"いえ"},{"t":"に"},{"t":"泊","r":"と"},{"t":"まりました"},{"t":"。"}]'::jsonb, 'In summer holidays, I often stayed at her house.'),
  ('rdg-ja-n4-my-grandmother-l7', 'rdg-ja-n4-my-grandmother', 7, 2, 'おばあちゃんは、野菜のスープを作ってくれました。', 'おばあちゃん わ、やさい の スープ お つくって くれました。', '[{"t":"おばあちゃん"},{"t":"は"},{"t":"、"},{"t":"野菜","r":"やさい"},{"t":"の"},{"t":"スープ"},{"t":"を"},{"t":"作","r":"つく"},{"t":"って"},{"t":"くれました"},{"t":"。"}]'::jsonb, 'She made me vegetable soup.'),
  ('rdg-ja-n4-my-grandmother-l8', 'rdg-ja-n4-my-grandmother', 8, 2, 'あの味は、今でも忘れられません。', 'あの あじ わ、いま でも わすれられません。', '[{"t":"あの"},{"t":"味","r":"あじ"},{"t":"は"},{"t":"、"},{"t":"今","r":"いま"},{"t":"でも"},{"t":"忘","r":"わす"},{"t":"れられません"},{"t":"。"}]'::jsonb, 'I still cannot forget that taste.'),
  ('rdg-ja-n4-my-grandmother-l9', 'rdg-ja-n4-my-grandmother', 9, 3, '夜は、昔の話を聞きました。', 'よる わ、むかし の はなし お ききました。', '[{"t":"夜","r":"よる"},{"t":"は"},{"t":"、"},{"t":"昔","r":"むかし"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"聞","r":"き"},{"t":"きました"},{"t":"。"}]'::jsonb, 'At night, I listened to stories from long ago.'),
  ('rdg-ja-n4-my-grandmother-l10', 'rdg-ja-n4-my-grandmother', 10, 3, '戦争の時代や、子どものころの遊びの話です。', 'せんそう の じだい や、こども の ころ の あそび の はなし です。', '[{"t":"戦争","r":"せんそう"},{"t":"の"},{"t":"時代","r":"じだい"},{"t":"や"},{"t":"、"},{"t":"子","r":"こ"},{"t":"ども"},{"t":"の"},{"t":"ころ"},{"t":"の"},{"t":"遊","r":"あそ"},{"t":"び"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"です"},{"t":"。"}]'::jsonb, 'Stories of wartime and the games of her childhood.'),
  ('rdg-ja-n4-my-grandmother-l11', 'rdg-ja-n4-my-grandmother', 11, 3, '聞くたびに、新しいことがわかりました。', 'きく たび に、あたらしい こと が わかりました。', '[{"t":"聞","r":"き"},{"t":"く"},{"t":"たびに"},{"t":"、"},{"t":"新","r":"あたら"},{"t":"しい"},{"t":"こと"},{"t":"が"},{"t":"わかりました"},{"t":"。"}]'::jsonb, 'Each time I listened, I learned something new.'),
  ('rdg-ja-n4-my-grandmother-l12', 'rdg-ja-n4-my-grandmother', 12, 4, '今は、遠くに住んでいるので、あまり会えません。', 'いま わ、とおく に すんで いる ので、あまり あえません。', '[{"t":"今","r":"いま"},{"t":"は"},{"t":"、"},{"t":"遠","r":"とお"},{"t":"く"},{"t":"に"},{"t":"住","r":"す"},{"t":"んで"},{"t":"いる"},{"t":"ので"},{"t":"、"},{"t":"あまり"},{"t":"会","r":"あ"},{"t":"えません"},{"t":"。"}]'::jsonb, 'Now I live far away, so I cannot see her much.'),
  ('rdg-ja-n4-my-grandmother-l13', 'rdg-ja-n4-my-grandmother', 13, 4, 'だから、毎週、電話をかけます。', 'だから、まいしゅう、でんわ お かけます。', '[{"t":"だから"},{"t":"、"},{"t":"毎週","r":"まいしゅう"},{"t":"、"},{"t":"電話","r":"でんわ"},{"t":"を"},{"t":"かけます"},{"t":"。"}]'::jsonb, 'So I call her every week.'),
  ('rdg-ja-n4-my-grandmother-l14', 'rdg-ja-n4-my-grandmother', 14, 4, 'おばあちゃん、いつまでも元気でいてください。', 'おばあちゃん、いつまでも げんき で いて ください。', '[{"t":"おばあちゃん"},{"t":"、"},{"t":"いつまでも"},{"t":"元気","r":"げんき"},{"t":"で"},{"t":"いて"},{"t":"ください"},{"t":"。"}]'::jsonb, 'Grandma, please stay well forever.'),
  ('rdg-ja-n4-my-grandmother-l15', 'rdg-ja-n4-my-grandmother', 15, 4, 'ありがとうございました。', 'ありがとうございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
