INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n4-a-concert-i-went-to-l0', 'rdg-ja-n4-a-concert-i-went-to', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n4-a-concert-i-went-to-l1', 'rdg-ja-n4-a-concert-i-went-to', 1, 0, '先週、はじめてコンサートに行きました。', 'せんしゅう、はじめて コンサート に いきました。', '[{"t":"先週","r":"せんしゅう"},{"t":"、"},{"t":"はじめて"},{"t":"コンサート"},{"t":"に"},{"t":"行","r":"い"},{"t":"きました"},{"t":"。"}]'::jsonb, 'Last week, I went to a concert for the first time.'),
  ('rdg-ja-n4-a-concert-i-went-to-l2', 'rdg-ja-n4-a-concert-i-went-to', 2, 0, '大好きな歌手の歌を聞きました。', 'だいすきな かしゅ の うた お ききました。', '[{"t":"大好","r":"だいす"},{"t":"き"},{"t":"な"},{"t":"歌手","r":"かしゅ"},{"t":"の"},{"t":"歌","r":"うた"},{"t":"を"},{"t":"聞","r":"き"},{"t":"きました"},{"t":"。"}]'::jsonb, 'I heard songs by my favourite singer.'),
  ('rdg-ja-n4-a-concert-i-went-to-l3', 'rdg-ja-n4-a-concert-i-went-to', 3, 1, 'チケットは、早めに買いました。', 'チケット わ、はやめ に かいました。', '[{"t":"チケット"},{"t":"は"},{"t":"、"},{"t":"早","r":"はや"},{"t":"めに"},{"t":"買","r":"か"},{"t":"いました"},{"t":"。"}]'::jsonb, 'I bought the ticket early.'),
  ('rdg-ja-n4-a-concert-i-went-to-l4', 'rdg-ja-n4-a-concert-i-went-to', 4, 1, 'すぐに売り切れたので、びっくりしました。', 'すぐ に うりきれた ので、びっくり しました。', '[{"t":"すぐ"},{"t":"に"},{"t":"売","r":"う"},{"t":"り"},{"t":"切","r":"き"},{"t":"れた"},{"t":"ので"},{"t":"、"},{"t":"びっくり"},{"t":"しました"},{"t":"。"}]'::jsonb, 'It sold out right away, so I was surprised.'),
  ('rdg-ja-n4-a-concert-i-went-to-l5', 'rdg-ja-n4-a-concert-i-went-to', 5, 1, 'その日から、毎日、楽しみにしていました。', 'その ひ から、まいにち、たのしみ に して いました。', '[{"t":"その"},{"t":"日","r":"ひ"},{"t":"から"},{"t":"、"},{"t":"毎日","r":"まいにち"},{"t":"、"},{"t":"楽","r":"たの"},{"t":"しみ"},{"t":"に"},{"t":"して"},{"t":"いました"},{"t":"。"}]'::jsonb, 'From that day, I looked forward to it every day.'),
  ('rdg-ja-n4-a-concert-i-went-to-l6', 'rdg-ja-n4-a-concert-i-went-to', 6, 2, '会場には、たくさんの人が来ていました。', 'かいじょう に わ、たくさん の ひと が きて いました。', '[{"t":"会場","r":"かいじょう"},{"t":"に"},{"t":"は"},{"t":"、"},{"t":"たくさん"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"が"},{"t":"来","r":"き"},{"t":"て"},{"t":"いました"},{"t":"。"}]'::jsonb, 'Many people had come to the hall.'),
  ('rdg-ja-n4-a-concert-i-went-to-l7', 'rdg-ja-n4-a-concert-i-went-to', 7, 2, '時間になると、急に暗くなりました。', 'じかん に なる と、きゅうに くらく なりました。', '[{"t":"時間","r":"じかん"},{"t":"に"},{"t":"なる"},{"t":"と"},{"t":"、"},{"t":"急","r":"きゅう"},{"t":"に"},{"t":"暗","r":"くら"},{"t":"くなりました"},{"t":"。"}]'::jsonb, 'When the time came, it suddenly got dark.'),
  ('rdg-ja-n4-a-concert-i-went-to-l8', 'rdg-ja-n4-a-concert-i-went-to', 8, 2, 'そして、大きなはくしゅが起こりました。', 'そして、おおきな はくしゅ が おこりました。', '[{"t":"そして"},{"t":"、"},{"t":"大","r":"おお"},{"t":"きな"},{"t":"はくしゅ"},{"t":"が"},{"t":"起","r":"お"},{"t":"こりました"},{"t":"。"}]'::jsonb, 'And then loud applause broke out.'),
  ('rdg-ja-n4-a-concert-i-went-to-l9', 'rdg-ja-n4-a-concert-i-went-to', 9, 3, '歌手が出てきたとき、私は思わず立ちました。', 'かしゅ が でて きた とき、わたし わ おもわず たちました。', '[{"t":"歌手","r":"かしゅ"},{"t":"が"},{"t":"出","r":"で"},{"t":"て"},{"t":"きた"},{"t":"とき"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"は"},{"t":"思","r":"おも"},{"t":"わず"},{"t":"立","r":"た"},{"t":"ちました"},{"t":"。"}]'::jsonb, 'When the singer came out, I stood up without thinking.'),
  ('rdg-ja-n4-a-concert-i-went-to-l10', 'rdg-ja-n4-a-concert-i-went-to', 10, 3, '私の好きな歌は、最後に歌ってくれました。', 'わたし の すきな うた わ、さいご に うたって くれました。', '[{"t":"私","r":"わたし"},{"t":"の"},{"t":"好","r":"す"},{"t":"き"},{"t":"な"},{"t":"歌","r":"うた"},{"t":"は"},{"t":"、"},{"t":"最後","r":"さいご"},{"t":"に"},{"t":"歌","r":"うた"},{"t":"って"},{"t":"くれました"},{"t":"。"}]'::jsonb, 'She sang my favourite song at the very end.'),
  ('rdg-ja-n4-a-concert-i-went-to-l11', 'rdg-ja-n4-a-concert-i-went-to', 11, 3, '私は、みんなと一緒に歌いました。', 'わたし わ、みんな と いっしょ に うたいました。', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"、"},{"t":"みんな"},{"t":"と"},{"t":"一緒","r":"いっしょ"},{"t":"に"},{"t":"歌","r":"うた"},{"t":"いました"},{"t":"。"}]'::jsonb, 'I sang along with everyone.'),
  ('rdg-ja-n4-a-concert-i-went-to-l12', 'rdg-ja-n4-a-concert-i-went-to', 12, 4, '帰り道も、まだ耳に音が残っていました。', 'かえりみち も、まだ みみ に おと が のこって いました。', '[{"t":"帰","r":"かえ"},{"t":"り"},{"t":"道","r":"みち"},{"t":"も"},{"t":"、"},{"t":"まだ"},{"t":"耳","r":"みみ"},{"t":"に"},{"t":"音","r":"おと"},{"t":"が"},{"t":"残","r":"のこ"},{"t":"って"},{"t":"いました"},{"t":"。"}]'::jsonb, 'On the way home, the sound still stayed in my ears.'),
  ('rdg-ja-n4-a-concert-i-went-to-l13', 'rdg-ja-n4-a-concert-i-went-to', 13, 4, '次のコンサートが、もう待ち遠しいです。', 'つぎ の コンサート が、もう まちどおしい です。', '[{"t":"次","r":"つぎ"},{"t":"の"},{"t":"コンサート"},{"t":"が"},{"t":"、"},{"t":"もう"},{"t":"待","r":"ま"},{"t":"ち"},{"t":"遠","r":"どお"},{"t":"しい"},{"t":"です"},{"t":"。"}]'::jsonb, 'I am already eager for the next concert.'),
  ('rdg-ja-n4-a-concert-i-went-to-l14', 'rdg-ja-n4-a-concert-i-went-to', 14, 4, 'おかげで、また仕事もがんばれそうです。', 'おかげで、また しごと も がんばれそう です。', '[{"t":"おかげで"},{"t":"、"},{"t":"また"},{"t":"仕事","r":"しごと"},{"t":"も"},{"t":"がんばれそう"},{"t":"です"},{"t":"。"}]'::jsonb, 'Thanks to it, I think I can work hard again.'),
