INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n4-going-camping-l0', 'rdg-ja-n4-going-camping', 0, 0, 'みなさん、おはようございます。', 'みなさん、おはよう ございます。', '[{"t":"みなさん"},{"t":"、"},{"t":"おはようございます"},{"t":"。"}]'::jsonb, 'Good morning, everyone.'),
  ('rdg-ja-n4-going-camping-l1', 'rdg-ja-n4-going-camping', 1, 0, '先月、家族とキャンプに行きました。', 'せんげつ、かぞく と キャンプ に いきました。', '[{"t":"先月","r":"せんげつ"},{"t":"、"},{"t":"家族","r":"かぞく"},{"t":"と"},{"t":"キャンプ"},{"t":"に"},{"t":"行","r":"い"},{"t":"きました"},{"t":"。"}]'::jsonb, 'Last month, I went camping with my family.'),
  ('rdg-ja-n4-going-camping-l2', 'rdg-ja-n4-going-camping', 2, 0, '私にとって、はじめてのキャンプでした。', 'わたし に とって、はじめて の キャンプ でした。', '[{"t":"私","r":"わたし"},{"t":"にとって"},{"t":"、"},{"t":"はじめて"},{"t":"の"},{"t":"キャンプ"},{"t":"でした"},{"t":"。"}]'::jsonb, 'It was my first time camping.'),
  ('rdg-ja-n4-going-camping-l3', 'rdg-ja-n4-going-camping', 3, 1, '車で二時間ぐらい走って、山に着きました。', 'くるま で にじかん ぐらい はしって、やま に つきました。', '[{"t":"車","r":"くるま"},{"t":"で"},{"t":"二時間","r":"にじかん"},{"t":"ぐらい"},{"t":"走","r":"はし"},{"t":"って"},{"t":"、"},{"t":"山","r":"やま"},{"t":"に"},{"t":"着","r":"つ"},{"t":"きました"},{"t":"。"}]'::jsonb, 'We drove for about two hours and reached the mountains.'),
  ('rdg-ja-n4-going-camping-l4', 'rdg-ja-n4-going-camping', 4, 1, '空気がきれいで、鳥の声が聞こえました。', 'くうき が きれいで、とり の こえ が きこえました。', '[{"t":"空気","r":"くうき"},{"t":"が"},{"t":"きれいで"},{"t":"、"},{"t":"鳥","r":"とり"},{"t":"の"},{"t":"声","r":"こえ"},{"t":"が"},{"t":"聞","r":"き"},{"t":"こえました"},{"t":"。"}]'::jsonb, 'The air was clean, and I could hear birds.'),
  ('rdg-ja-n4-going-camping-l5', 'rdg-ja-n4-going-camping', 5, 1, 'まず、みんなでテントを立て始めました。', 'まず、みんな で テント お たて はじめました。', '[{"t":"まず"},{"t":"、"},{"t":"みんな"},{"t":"で"},{"t":"テント"},{"t":"を"},{"t":"立","r":"た"},{"t":"て"},{"t":"始","r":"はじ"},{"t":"めました"},{"t":"。"}]'::jsonb, 'First, we all started putting up the tent.'),
  ('rdg-ja-n4-going-camping-l6', 'rdg-ja-n4-going-camping', 6, 2, 'でも、テントは、なかなか立ちませんでした。', 'でも、テント わ、なかなか たちません でした。', '[{"t":"でも"},{"t":"、"},{"t":"テント"},{"t":"は"},{"t":"、"},{"t":"なかなか"},{"t":"立","r":"た"},{"t":"ちませんでした"},{"t":"。"}]'::jsonb, 'But the tent would not stand up at all.'),
  ('rdg-ja-n4-going-camping-l7', 'rdg-ja-n4-going-camping', 7, 2, '父と二人で、一時間もかかりました。', 'ちち と ふたり で、いちじかん も かかりました。', '[{"t":"父","r":"ちち"},{"t":"と"},{"t":"二人","r":"ふたり"},{"t":"で"},{"t":"、"},{"t":"一時間","r":"いちじかん"},{"t":"も"},{"t":"かかりました"},{"t":"。"}]'::jsonb, 'It took my father and me a whole hour.'),
  ('rdg-ja-n4-going-camping-l8', 'rdg-ja-n4-going-camping', 8, 2, 'やっと立ったとき、みんなではくしゅしました。', 'やっと たった とき、みんな で はくしゅ しました。', '[{"t":"やっと"},{"t":"立","r":"た"},{"t":"った"},{"t":"とき"},{"t":"、"},{"t":"みんな"},{"t":"で"},{"t":"はくしゅ"},{"t":"しました"},{"t":"。"}]'::jsonb, 'When it finally stood, we all clapped.'),
  ('rdg-ja-n4-going-camping-l9', 'rdg-ja-n4-going-camping', 9, 3, '夜は、火のまわりでカレーを食べました。', 'よる わ、ひ の まわり で カレー お たべました。', '[{"t":"夜","r":"よる"},{"t":"は"},{"t":"、"},{"t":"火","r":"ひ"},{"t":"の"},{"t":"まわり"},{"t":"で"},{"t":"カレー"},{"t":"を"},{"t":"食","r":"た"},{"t":"べました"},{"t":"。"}]'::jsonb, 'At night, we ate curry around the fire.'),
  ('rdg-ja-n4-going-camping-l10', 'rdg-ja-n4-going-camping', 10, 3, '外で食べると、いつもよりおいしいです。', 'そと で たべる と、いつも より おいしい です。', '[{"t":"外","r":"そと"},{"t":"で"},{"t":"食","r":"た"},{"t":"べる"},{"t":"と"},{"t":"、"},{"t":"いつも"},{"t":"より"},{"t":"おいしい"},{"t":"です"},{"t":"。"}]'::jsonb, 'Eating outside, it tastes better than usual.'),
  ('rdg-ja-n4-going-camping-l11', 'rdg-ja-n4-going-camping', 11, 3, '空を見ると、星がたくさん見えました。', 'そら お みる と、ほし が たくさん みえました。', '[{"t":"空","r":"そら"},{"t":"を"},{"t":"見","r":"み"},{"t":"る"},{"t":"と"},{"t":"、"},{"t":"星","r":"ほし"},{"t":"が"},{"t":"たくさん"},{"t":"見","r":"み"},{"t":"えました"},{"t":"。"}]'::jsonb, 'Looking at the sky, I saw so many stars.'),
  ('rdg-ja-n4-going-camping-l12', 'rdg-ja-n4-going-camping', 12, 4, '夜中は少し寒くて、あまり寝られませんでした。', 'よなか わ すこし さむくて、あまり ねられません でした。', '[{"t":"夜中","r":"よなか"},{"t":"は"},{"t":"少","r":"すこ"},{"t":"し"},{"t":"寒","r":"さむ"},{"t":"くて"},{"t":"、"},{"t":"あまり"},{"t":"寝","r":"ね"},{"t":"られませんでした"},{"t":"。"}]'::jsonb, 'It was a little cold in the night, and I could hardly sleep.'),
  ('rdg-ja-n4-going-camping-l13', 'rdg-ja-n4-going-camping', 13, 4, 'でも、朝の山は、とてもきれいでした。', 'でも、あさ の やま わ、とても きれい でした。', '[{"t":"でも"},{"t":"、"},{"t":"朝","r":"あさ"},{"t":"の"},{"t":"山","r":"やま"},{"t":"は"},{"t":"、"},{"t":"とても"},{"t":"きれい"},{"t":"でした"},{"t":"。"}]'::jsonb, 'But the mountain in the morning was so beautiful.'),
  ('rdg-ja-n4-going-camping-l14', 'rdg-ja-n4-going-camping', 14, 4, 'また、みんなで行きたいです。', 'また、みんな で いきたい です。', '[{"t":"また"},{"t":"、"},{"t":"みんな"},{"t":"で"},{"t":"行","r":"い"},{"t":"きたい"},{"t":"です"},{"t":"。"}]'::jsonb, 'I want to go again with everyone.'),
  ('rdg-ja-n4-going-camping-l15', 'rdg-ja-n4-going-camping', 15, 4, 'ありがとうございました。', 'ありがとうございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n4-going-camping')
