INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n4-my-job-interview-l0', 'rdg-ja-n4-my-job-interview', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n4-my-job-interview-l1', 'rdg-ja-n4-my-job-interview', 1, 0, '先週、会社のめんせつを受けました。', 'せんしゅう、かいしゃ の めんせつ お うけました。', '[{"t":"先週","r":"せんしゅう"},{"t":"、"},{"t":"会社","r":"かいしゃ"},{"t":"の"},{"t":"めんせつ"},{"t":"を"},{"t":"受","r":"う"},{"t":"けました"},{"t":"。"}]'::jsonb, 'Last week, I had an interview at a company.'),
  ('rdg-ja-n4-my-job-interview-l2', 'rdg-ja-n4-my-job-interview', 2, 0, 'そのときの気持ちを話します。', 'その とき の きもち お はなします。', '[{"t":"その"},{"t":"とき"},{"t":"の"},{"t":"気持","r":"きも"},{"t":"ち"},{"t":"を"},{"t":"話","r":"はな"},{"t":"します"},{"t":"。"}]'::jsonb, 'I will tell you how I felt then.'),
  ('rdg-ja-n4-my-job-interview-l3', 'rdg-ja-n4-my-job-interview', 3, 1, '朝から、むねがどきどきしていました。', 'あさ から、むね が どきどき して いました。', '[{"t":"朝","r":"あさ"},{"t":"から"},{"t":"、"},{"t":"むね"},{"t":"が"},{"t":"どきどき"},{"t":"して"},{"t":"いました"},{"t":"。"}]'::jsonb, 'From morning, my heart was pounding.'),
  ('rdg-ja-n4-my-job-interview-l4', 'rdg-ja-n4-my-job-interview', 4, 1, '新しいシャツを着て、早く家を出ました。', 'あたらしい シャツ お きて、はやく いえ お でました。', '[{"t":"新","r":"あたら"},{"t":"しい"},{"t":"シャツ"},{"t":"を"},{"t":"着","r":"き"},{"t":"て"},{"t":"、"},{"t":"早","r":"はや"},{"t":"く"},{"t":"家","r":"いえ"},{"t":"を"},{"t":"出","r":"で"},{"t":"ました"},{"t":"。"}]'::jsonb, 'I put on a new shirt and left home early.'),
  ('rdg-ja-n4-my-job-interview-l5', 'rdg-ja-n4-my-job-interview', 5, 1, '遅れたくなかったからです。', 'おくれたくなかった から です。', '[{"t":"遅","r":"おく"},{"t":"れた"},{"t":"くなかった"},{"t":"から"},{"t":"です"},{"t":"。"}]'::jsonb, 'It was because I did not want to be late.'),
  ('rdg-ja-n4-my-job-interview-l6', 'rdg-ja-n4-my-job-interview', 6, 2, '会社に着いて、部屋で待ちました。', 'かいしゃ に ついて、へや で まちました。', '[{"t":"会社","r":"かいしゃ"},{"t":"に"},{"t":"着","r":"つ"},{"t":"いて"},{"t":"、"},{"t":"部屋","r":"へや"},{"t":"で"},{"t":"待","r":"ま"},{"t":"ちました"},{"t":"。"}]'::jsonb, 'I arrived at the company and waited in a room.'),
  ('rdg-ja-n4-my-job-interview-l7', 'rdg-ja-n4-my-job-interview', 7, 2, '名前を呼ばれて、中に入りました。', 'なまえ お よばれて、なか に はいりました。', '[{"t":"名前","r":"なまえ"},{"t":"を"},{"t":"呼","r":"よ"},{"t":"ばれて"},{"t":"、"},{"t":"中","r":"なか"},{"t":"に"},{"t":"入","r":"はい"},{"t":"りました"},{"t":"。"}]'::jsonb, 'My name was called, and I went inside.'),
  ('rdg-ja-n4-my-job-interview-l8', 'rdg-ja-n4-my-job-interview', 8, 2, '三人の人が、私を見ていました。', 'さんにん の ひと が、わたし お みて いました。', '[{"t":"三人","r":"さんにん"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"が"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"を"},{"t":"見","r":"み"},{"t":"て"},{"t":"いました"},{"t":"。"}]'::jsonb, 'Three people were looking at me.'),
  ('rdg-ja-n4-my-job-interview-l9', 'rdg-ja-n4-my-job-interview', 9, 3, '「どうして、この会社で働きたいですか」と聞かれました。', '「どうして、この かいしゃ で はたらきたい です か」と きかれました。', '[{"t":"「"},{"t":"どうして"},{"t":"、"},{"t":"この"},{"t":"会社","r":"かいしゃ"},{"t":"で"},{"t":"働","r":"はたら"},{"t":"きたい"},{"t":"です"},{"t":"か"},{"t":"」"},{"t":"と"},{"t":"聞","r":"き"},{"t":"かれました"},{"t":"。"}]'::jsonb, 'I was asked, "Why do you want to work at this company?"'),
  ('rdg-ja-n4-my-job-interview-l10', 'rdg-ja-n4-my-job-interview', 10, 3, '私は、ゆっくり考えて答えました。', 'わたし わ、ゆっくり かんがえて こたえました。', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"、"},{"t":"ゆっくり"},{"t":"考","r":"かんが"},{"t":"えて"},{"t":"答","r":"こた"},{"t":"えました"},{"t":"。"}]'::jsonb, 'I thought slowly and answered.'),
  ('rdg-ja-n4-my-job-interview-l11', 'rdg-ja-n4-my-job-interview', 11, 3, '「人と話すのが好きだからです」と言いました。', '「ひと と はなす の が すきだ から です」と いいました。', '[{"t":"「"},{"t":"人","r":"ひと"},{"t":"と"},{"t":"話","r":"はな"},{"t":"す"},{"t":"の"},{"t":"が"},{"t":"好","r":"す"},{"t":"き"},{"t":"だ"},{"t":"から"},{"t":"です"},{"t":"」"},{"t":"と"},{"t":"言","r":"い"},{"t":"いました"},{"t":"。"}]'::jsonb, 'I said, "Because I like talking with people."'),
  ('rdg-ja-n4-my-job-interview-l12', 'rdg-ja-n4-my-job-interview', 12, 4, '終わったとき、体の力がぬけました。', 'おわった とき、からだ の ちから が ぬけました。', '[{"t":"終","r":"お"},{"t":"わった"},{"t":"とき"},{"t":"、"},{"t":"体","r":"からだ"},{"t":"の"},{"t":"力","r":"ちから"},{"t":"が"},{"t":"ぬけました"},{"t":"。"}]'::jsonb, 'When it ended, the strength left my body.'),
  ('rdg-ja-n4-my-job-interview-l13', 'rdg-ja-n4-my-job-interview', 13, 4, 'うまく話せたかどうか、わかりません。', 'うまく はなせた か どうか、わかりません。', '[{"t":"うまく"},{"t":"話","r":"はな"},{"t":"せ"},{"t":"た"},{"t":"かどうか"},{"t":"、"},{"t":"わかりません"},{"t":"。"}]'::jsonb, 'I do not know whether I spoke well.'),
  ('rdg-ja-n4-my-job-interview-l14', 'rdg-ja-n4-my-job-interview', 14, 4, 'でも、最後までがんばれて、よかったです。', 'でも、さいご まで がんばれて、よかった です。', '[{"t":"でも"},{"t":"、"},{"t":"最後","r":"さいご"},{"t":"まで"},{"t":"がんばれて"},{"t":"、"},{"t":"よかった"},{"t":"です"},{"t":"。"}]'::jsonb, 'But I am glad I managed to do my best to the end.'),
  ('rdg-ja-n4-my-job-interview-l15', 'rdg-ja-n4-my-job-interview', 15, 4, 'ありがとうございました。', 'ありがとうございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
