INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n4-new-year-in-japan-l0', 'rdg-ja-n4-new-year-in-japan', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n4-new-year-in-japan-l1', 'rdg-ja-n4-new-year-in-japan', 1, 0, '去年は、お正月を日本で過ごしました。', 'きょねん わ、おしょうがつ お にほん で すごしました。', '[{"t":"去年","r":"きょねん"},{"t":"は"},{"t":"、"},{"t":"お"},{"t":"正月","r":"しょうがつ"},{"t":"を"},{"t":"日本","r":"にほん"},{"t":"で"},{"t":"過","r":"す"},{"t":"ごしました"},{"t":"。"}]'::jsonb, 'Last year I spent New Year in Japan.'),
  ('rdg-ja-n4-new-year-in-japan-l2', 'rdg-ja-n4-new-year-in-japan', 2, 0, '今日は、お正月の話をします。', 'きょう わ、おしょうがつ の はなし お します。', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"お"},{"t":"正月","r":"しょうがつ"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'Today I will tell you about New Year.'),
  ('rdg-ja-n4-new-year-in-japan-l3', 'rdg-ja-n4-new-year-in-japan', 3, 1, '大みそかの夜、友だちの家に行きました。', 'おおみそか の よる、ともだち の いえ に いきました。', '[{"t":"大","r":"おお"},{"t":"みそか"},{"t":"の"},{"t":"夜","r":"よる"},{"t":"、"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"の"},{"t":"家","r":"いえ"},{"t":"に"},{"t":"行","r":"い"},{"t":"きました"},{"t":"。"}]'::jsonb, 'On New Year''s Eve, I went to a friend''s house.'),
  ('rdg-ja-n4-new-year-in-japan-l4', 'rdg-ja-n4-new-year-in-japan', 4, 1, 'みんなで、そばを食べました。', 'みんな で、そば お たべました。', '[{"t":"みんな"},{"t":"で"},{"t":"、"},{"t":"そば"},{"t":"を"},{"t":"食","r":"た"},{"t":"べました"},{"t":"。"}]'::jsonb, 'We all ate soba together.'),
  ('rdg-ja-n4-new-year-in-japan-l5', 'rdg-ja-n4-new-year-in-japan', 5, 1, '長生きできるように、という意味があるそうです。', 'ながいき できる よう に、と いう いみ が ある そう です。', '[{"t":"長生","r":"ながい"},{"t":"き"},{"t":"できる"},{"t":"よう"},{"t":"に"},{"t":"、"},{"t":"という"},{"t":"意味","r":"いみ"},{"t":"が"},{"t":"ある"},{"t":"そう"},{"t":"です"},{"t":"。"}]'::jsonb, 'I heard it is a wish for a long life.'),
  ('rdg-ja-n4-new-year-in-japan-l6', 'rdg-ja-n4-new-year-in-japan', 6, 2, '夜の十二時に、お寺のかねが鳴りました。', 'よる の じゅうにじ に、おてら の かね が なりました。', '[{"t":"夜","r":"よる"},{"t":"の"},{"t":"十二時","r":"じゅうにじ"},{"t":"に"},{"t":"、"},{"t":"お"},{"t":"寺","r":"てら"},{"t":"の"},{"t":"かね"},{"t":"が"},{"t":"鳴","r":"な"},{"t":"りました"},{"t":"。"}]'::jsonb, 'At midnight, the temple bell rang.'),
  ('rdg-ja-n4-new-year-in-japan-l7', 'rdg-ja-n4-new-year-in-japan', 7, 2, 'かねは、ひゃくはっかい鳴るそうです。', 'かね わ、ひゃくはっかい なる そう です。', '[{"t":"かね"},{"t":"は"},{"t":"、"},{"t":"ひゃくはっかい"},{"t":"鳴","r":"な"},{"t":"る"},{"t":"そう"},{"t":"です"},{"t":"。"}]'::jsonb, 'I hear the bell rings one hundred and eight times.'),
  ('rdg-ja-n4-new-year-in-japan-l8', 'rdg-ja-n4-new-year-in-japan', 8, 2, '寒かったけれど、とても静かな時間でした。', 'さむかった けれど、とても しずかな じかん でした。', '[{"t":"寒","r":"さむ"},{"t":"かったけれど"},{"t":"、"},{"t":"とても"},{"t":"静","r":"しず"},{"t":"か"},{"t":"な"},{"t":"時間","r":"じかん"},{"t":"でした"},{"t":"。"}]'::jsonb, 'It was cold, but it was a very quiet time.'),
  ('rdg-ja-n4-new-year-in-japan-l9', 'rdg-ja-n4-new-year-in-japan', 9, 3, '一月一日の朝、神社にお参りに行きました。', 'いちがつ ついたち の あさ、じんじゃ に おまいり に いきました。', '[{"t":"一月","r":"いちがつついたち"},{"t":"一日"},{"t":"の"},{"t":"朝","r":"あさ"},{"t":"、"},{"t":"神社","r":"じんじゃ"},{"t":"に"},{"t":"お"},{"t":"参","r":"まい"},{"t":"り"},{"t":"に"},{"t":"行","r":"い"},{"t":"きました"},{"t":"。"}]'::jsonb, 'On the morning of January first, I went to a shrine.'),
  ('rdg-ja-n4-new-year-in-japan-l10', 'rdg-ja-n4-new-year-in-japan', 10, 3, '多くの人が、ならんでいました。', 'おおく の ひと が、ならんで いました。', '[{"t":"多","r":"おお"},{"t":"くの"},{"t":"人","r":"ひと"},{"t":"が"},{"t":"、"},{"t":"ならんで"},{"t":"いました"},{"t":"。"}]'::jsonb, 'Many people were standing in line.'),
  ('rdg-ja-n4-new-year-in-japan-l11', 'rdg-ja-n4-new-year-in-japan', 11, 3, '私は、今年も元気でいられますようにと、ねがいました。', 'わたし わ、ことし も げんき で いられます よう に と、ねがいました。', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"、"},{"t":"今年","r":"ことし"},{"t":"も"},{"t":"元気","r":"げんき"},{"t":"で"},{"t":"いられます"},{"t":"よう"},{"t":"に"},{"t":"と"},{"t":"、"},{"t":"ねがいました"},{"t":"。"}]'::jsonb, 'I wished that I could stay well this year too.'),
  ('rdg-ja-n4-new-year-in-japan-l12', 'rdg-ja-n4-new-year-in-japan', 12, 4, '家に帰って、おせち料理を食べました。', 'いえ に かえって、おせちりょうり お たべました。', '[{"t":"家","r":"いえ"},{"t":"に"},{"t":"帰","r":"かえ"},{"t":"って"},{"t":"、"},{"t":"おせち"},{"t":"料理","r":"りょうり"},{"t":"を"},{"t":"食","r":"た"},{"t":"べました"},{"t":"。"}]'::jsonb, 'Back home, I ate osechi food.'),
  ('rdg-ja-n4-new-year-in-japan-l13', 'rdg-ja-n4-new-year-in-japan', 13, 4, '小さな子どもたちは、おとしだまをもらっていました。', 'ちいさな こどもたち わ、おとしだま お もらって いました。', '[{"t":"小","r":"ちい"},{"t":"さな"},{"t":"子","r":"こ"},{"t":"ども"},{"t":"たち"},{"t":"は"},{"t":"、"},{"t":"おとしだま"},{"t":"を"},{"t":"もらって"},{"t":"いました"},{"t":"。"}]'::jsonb, 'The little children were receiving New Year money gifts.'),
  ('rdg-ja-n4-new-year-in-japan-l14', 'rdg-ja-n4-new-year-in-japan', 14, 4, '静かで、あたたかいお正月でした。', 'しずか で、あたたかい おしょうがつ でした。', '[{"t":"静","r":"しず"},{"t":"か"},{"t":"で"},{"t":"、"},{"t":"あたたかい"},{"t":"お"},{"t":"正月","r":"しょうがつ"},{"t":"でした"},{"t":"。"}]'::jsonb, 'It was a quiet, warm New Year.'),
  ('rdg-ja-n4-new-year-in-japan-l15', 'rdg-ja-n4-new-year-in-japan', 15, 4, 'ありがとうございました。', 'ありがとうございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
